# -*- coding: utf-8 -*-
"""МОВНИЙ ШАР: мовна модель між людиною й системою. Мову розуміє й пише лише вона.

РІШЕННЯ ВЛАСНИКА 27.09.2026 (М-5, аудит/ПРОДУКТ.md п.14) ЗМІНЮЄ РОЛЬ «ЛИШЕ ПЕРЕКЛАДАЧ» З 25.09: «Не можна
якісно перекладати та інтерпретувати бажання людини, якщо брати кожне повідомлення окремо. Мовна
модель має спілкуватися і заповнювати паспорт осмислено.» «Мовна модель веде живу розмову з
користувачем. Її задача — зрозуміти запит користувача і перекласти його на мову, яку розуміє
система. Мовна модель викликає на допомогу код та ші стиліста, тільки якщо користувач прямо в чаті
хоче отримати відповідь, яку впевнено можуть дати лише код + ші.» Тож у розмові хід — ОДИН виклик
(«ХІД РОЗМОВИ» нижче: `промпт_розмови` / `прийняти_розмову`): модель бачить розмову, паспорт і
профіль, оновлює паспорт кодами й відповідає сама; код лишається суддею паспорта й правил п.9. Два
перекладачі нижче лишаються там, де розмови нема (коментар до образу, питання екрана оцінки) і
де зміст дає код (перекладач репліки — другий виклик ходу, лише коли він потрібен; тексти картки).

РІШЕННЯ ВЛАСНИКА 25.09.2026 (дослівно): «Модель, спеціаліст з української мови, просто
робить весь текст, що бачить людина, природним. Вона сама не приймає жодних рішень, не
відповідає на питання, не обробляє інформацію і не збирає образи. Це перекладач.» Того ж
дня: «Зараз мова і всі проблеми з її розумінням і інтерпретацією віддані спеціалізованій
моделі. Всі інші костилі не потрібні. <…> Перекладом і інтерпретацією займається лише
спеціальна українська модель.» І: «Українська модель перекладає всі слова людини на
зрозумілу для інших частин системи мову.»

ДВА ПЕРЕКЛАДАЧІ Й ВНУТРІШНЯ МОВА (`внутрішня_мова`: коди, числа, id, "unknown").
  · ВХІД — слова жінки (репліка про сценарій, коментар до образу) → внутрішня мова
    (`промпт_входу` / `прийняти_вхід`). Далі код працює зі структурою: `паспорт_з_шару`
    перекладає коди в ключі ядра ОДНІЄЮ таблицею (`внутрішня_мова.ТАБЛИЦЯ`) і збирає
    паспорт тим самим `паспорт_з_json`, що й доти, — без словників і гейтів, які читали
    її слова: коли шар увімкнено, вони не стоять на його шляху.
  · ВИХІД — те, що код і моделі кажуть жінці, → природна мова: репліка стилістки
    внутрішньою мовою (`промпт_репліки` / `прийняти_репліку`, ОДНЕ поле `text`), рядки
    картки образу й екрана «Палітра» внутрішньою мовою (`промпт_повідомлень` /
    `прийняти_повідомлення`: вид рядка + заяви кодами — Ч-1, аудит/ПРОДУКТ.md п.12) і готові
    тексти, які склали ФУНКЦІОНАЛЬНІ моделі (`промпт` / `прийняти`).
Промпти — лише роль, вхід, схема полів і межа («невідомо»); без прикладів-фраз.

Змісту код не судить: точність видно у звіті власника — на кожен виклик шару там стоїть
вхід, вихід (для входу — внутрішня мова повністю), модель і час, — а міряє її ноутбук
(`проби/мова_шару_вимір.py`, `проби/мова_входу_вимір.py`). Мовчки не губиться нічого:
код поза переліком стоїть у `незнайомі`, текст без відповіді — у `без_відповіді`.

БЕЗ МОДЕЛІ ШАРУ ВСЕ ЯК ДОТИ: показ не кличе цей модуль.
"""
