# перемішує руки, а не вибірку моделі: запит шару йшов без температури, тобто з тією, що
# стоїть у LM Studio. Перекладач нічого не вигадує — переносить, тож вибірка йому ні до чого:
# температура 0 — жадібне декодування, той самий промпт дає той самий вихід. СІДА НЕМА
