# відкидає 400-кою («Extra inputs are not permitted») — маршрут `claude-` упав би на першому ж
# виклику шару. Ендпойнт віддає ці поля поруч із КОЖНИМ промптом шару (вхід, вихід, репліка);
# показ кладе їх у тіло виклику, стенд ноутбука пересилає в LM Studio.
# МІСТ ЇХ ПЕРЕСИЛАЄ (рядок 158 дошки, 27.09.2026). Доти цей рядок казав «міст Gemini їх не
# пересилає», і так воно й було: маршрут `gemini-` будує тіло нанову й брав із нього лише
# стелю виводу й мислення, тобто температура зникала МОВЧКИ саме на тому провайдері, де
# крутиться шар, — рішення «температура 0» не діяло ніде, крім LM Studio ноутбука. Тепер
# число доїжджає до обох провайдерів (`worker_джерело.js`, `температура_тіла`), і що поїхало,
# каже заголовок `x-temperature`. Ціна названа: для Gemini 3 Google радить лишати 1.0, і
