# ── МОВА ТЕКСТУ ДЛЯ НЕЇ: ЛИШЕ ЯК ТРЕБА, БЕЗ АНТИПРИКЛАДІВ (рядки 1432, 1433; розбір 02.10) ──────────
# ЩО БУЛО ВИДНО. Шаблон казав «не «личить personally»… не «spідниця»», і саме ці слова модель і писала:
# «бордова спідниця тобі personally личить», «spідниця кльош» — 8 відповідей у 8 прогонах; антиприклад
# у промпті — теж приклад. А мовних вад, яких у промпті не було, — «брюки», «туфлі-лодочки», «дресовіше»,
# «тауп», «з м'якого замшу», самоправка посеред речення, «ви» в питанні — 32 картки в 22 прогонах.
# ЩО ТЕПЕР. Межа сказана лише тим, як писати: однією абеткою, остаточною версією, звичними українськими
# назвами — перелік із англійського слова ДЖЕРЕЛА (опис функціональна модель пише англійською, п.12),
# а не з поганих українських форм. Слів код не читає й не пише (п.12): це текст промпта, який читає лише
# мовна модель. Ті самі рядки — у трьох перекладачок виходу: тексти, репліка, повідомлення.
# Рядок 3311 (живі 12, Б/03 сід 5): «Ти обрала штани з м'якої замші» — у вході репліки назви речі не було, а
# «штани» й «з м'якої замші» — перше й останнє слово словничка; на фото — біла шкіряна сандаля. Словничок —
# лише переклад слів, які є в її вході: так і сказано, а готової фрази-зразка в ньому нема.
# Рядок 4470 (сцена 13 після #891, seed3_48 → seed3_51): «This camel sweater…» перекладачка дала «Цей кашеміровий
# светр», «кашеміровий светр капучино» — колір став тканиною (річ — `fabric: jersey`, «Светр-павутинка капучино
# кемел»). Слів код не читає (п.12): `camel` у словничку названо кольором.
МОВА_ДЛЯ_НЕЇ = ("Мова: літературна українська, як у текстах українських крамниць одягу. Кожне українське слово — "
               "літерами лише української абетки, без жодної латинської літери чи стороннього знака "
               "всередині слова. Кожне речення — одна остаточна версія, без виправлень посеред тексту. "
               "Словничок нижче — лише як перекласти англійське слово, коли воно є у вході; це не зміст: "
               "річ, тканина чи колір, яких у вході нема, у тексті не з'являються. Звичні українські назви "
               "для слів англійського джерела: trousers, pants — штани; dressy, dressier — ошатний, ошатніше; "
               "look, outfit — образ; taupe — сіро-бежевий; loose — вільний; suede — замша (жіночий рід); "
               "slip dress — сукня-комбінація; camel — кемел (колір). Назви речей і кольорів, які дала "
               "крамниця, — як є.")
