# переліком у «Вид кожної речі…» (6196). Речення про `виправ` їхало в кожен виклик, а `виправ` буває лише в повторі
# (живі пачки 15 — 2 з 50 викликів): `промпт` дописує `РЕЧЕННЯ_ВИПРАВ` за `ВХІД_ВИХОДУ` лише тоді (6197).
# ВХІД — ТІЄЮ САМОЮ МАПОЮ, ЩО Й ВІДПОВІДЬ (рядок 6752, ОЦІНКА-ЖИВІ-1016-3). Тексти йшли масивом `[{"н": 1, "текст": …},
# …]`, а відповідь мала бути мапою `{"1": …}`. MamayLM дзеркалила вхідну форму одним елементом — `{"н": 1, "текст": …}`:
# зима рука 1 (13 і 12 текстів, `seed3_31`, `_33`) — переклад лише н=1, повтор того самого промпта — знову н=1, і
# картка без «Чому цей образ»; replay 5820 на вокалі — та сама відповідь, вісім абзаців лишились англійськими. Тепер
# тексти стоять мапою «номер → текст», тож віддзеркалений вхід — це й є відповідь потрібної форми. Текст із `виправ`
# (повтор) стоїть значенням-об'єктом {текст, виправ}; переклад у такій самій формі розбір читає (`_з_форми`).
ВХІД_ВИХОДУ = "Вхід — JSON-об'єкт: ключ — номер тексту н, значення — текст, який склали код та інші моделі."
РЕЧЕННЯ_ВИПРАВ = (" Значення-об'єкт {текст, виправ} несе текст, який ти вже переклала, а виправ — слова в ньому, написані не "
                  "українською кирилицею чи з битими знаками: перепиши українською лише ці слова, решту тексту лиши "
                  "слово в слово.")
ПРОМПТ_ВИХОДУ = """Ти — перекладачка в застосунку-стилістці. Ти пишеш природною українською тексти, які зараз побачить жінка. Рішень не приймаєш, на питання не відповідаєш, змісту не міняєш.

""" + ВХІД_ВИХОДУ + """

Відповідь — лише JSON-об'єкт тієї самої форми, що вхід, з усіма його ключами: ключ — номер н кожного тексту зі входу, значення — рядок — той самий зміст природною українською, без англійських слів і кодів (назви крамниць і брендів — як є); ПЕРЕКЛАДАЙ КОЖНЕ англійське слово, навіть одне посеред українського речення; латиницею лишай лише назви крамниць і брендів, «V-подібний» і «den»; текст, що вже природний і до неї на «ти», — без змін, а український текст на «ви» перепиши на «ти», решту лиши слово в слово.

Вид кожної речі — теж зміст: річ у перекладі — та сама, що у вході, а не схожа чи сусідня. ankle boots — черевики чи ботильйони, boots — чоботи, heeled — на підборах, а не туфлі, pumps — туфлі-човники, loafers — лофери; pendant — кулон чи підвіска, necklace — намисто чи ланцюжок, а не каблучка, сережки чи браслет; ring — каблучка; earrings — сережки. Українські назви речей у вході (назви з крамниці, найчастіше перед « — ») переписуй літера в літеру: не міняй, не переставляй і не додавай у них жодного слова.

Про жінку — лише до неї, на """ + _ЗВЕРТАННЯ_ТИ + """, і в питаннях теж: you, your, she, her про неї — «ти», «твій» (her skin tone — твій тон шкіри; when she turns her head — коли ти повертаєш голову; she looks taller — ти виглядаєш вищою), англійський наказ — наказом однини; «вона», «її» — лише про річ (сукню, сумку, куртку); стилістка про себе — у жіночому роді.

""" + МОВА_ДЛЯ_НЕЇ + """

Перевір кожне слово ДО відповіді: до неї — лише «ти», жодного «ви», «ваш» і наказу множини, і про неї жодного «вона», «її», «їй», жодне слово не стоїть двічі поспіль, кожна річ — того самого виду, що у вході (річ образу — іменником її назви з переліку, коли він є, і слова при ній узгоджені з цим іменником), а українська назва речі — слово в слово. Відповідь — рівно ОДИН JSON-об'єкт і нічого після нього: другої, виправленої версії, приміток і пояснень не пиши — помилку виправ у тому самому об'єкті.

ТЕКСТИ:
"""


# ── КОЛІР У ТЕКСТІ ДЛЯ НЕЇ — КОДОМ, А НЕ ДІРКОЮ (рядок 3934; п.12, п.18) ────────────────────────────────────
# ЩО БУЛО ВИДНО. Руки 3–4 пишуть річ «… color #059669, fabric: lustrous silk» (промпт руки просить «color with its
# hex code», п.1 — не міняється). Показ знімав hex як машинний слід ще ДО шару, і шар перекладав «колір, тканина:
# блискучий шовк» — колір словом не доходив до картки (ЖИВІ-15 №11 — 3 рази, №12 — 1; у №12 hex сукні — тон її
# шкіри). ЩО ТЕПЕР. Показ віддає шару текст із hex (`людською(…, лишитиHex)`), а тут hex стає кодом `color_name`
# тим самим правилом, що підписує палітру (`palettes._назва`: найтісніше вікно лексикону, п.18), — «[colour: camel]».
# Слово пише шар: у промпт ідуть лише вжиті коди з внутрішнім словом ядра (як `_типи_речей`). Ярлик «hex» і дужки
# навколо значення йдуть разом із ним: «graphite (hex #2C2F33)» — один колір, а не два. Колір, якому коду нема
# («невідомо»), знімається, як доти знімав показ.
# Ярлик перед hex («color», «colour code:», «code») і дужки за ним теж ловляться: коли hex знімається без коду, а
# в дужках її назва, лишається сама назва — «color #8fbc8f (sage green)» → «sage green»; доти перекладач отримував
# «color (sage green)» і писав «колір (салатовий)» (рядок 4511). Hex з кодом ярлик і дужки лишає як доти.
_HEX_У_ТЕКСТІ = re.compile(r"(?P<ярлик>\b(?:colou?r|code)\b(?:\s+code\b)?\s*[:=]?\s*)?"
                           r"(?P<hx>\(\s*(?:\bhex\b\s*(?:code\s*)?[:=]?\s*)?#([0-9a-fA-F]{6})\b\s*\)"
                           r"|(?:\bhex\b\s*(?:code\s*)?[:=]?\s*)?#([0-9a-fA-F]{6})\b)"
                           r"(?P<дужки>\s*\(([^()\n]*)\))?", re.I)
_КОД_КОЛЬОРУ = re.compile(r"\[colour: ([a-z_]+)\]")


def _код_кольору(hex_):
    """«059669» → код `color_name` (`palettes._назва` — те саме вікно, що підписує палітру) або None."""
    import palettes as _ПЛ
    import colorspace as _cs
    к = _ВМ.код("color_name", _ПЛ._назва(_cs.hx("#" + hex_))[0])
    return к if к and not _ВМ.невідомо(к) else None


# ЯКЩО СТИЛІСТКА ВЖЕ НАЗВАЛА КОЛІР РЕЧІ, ДРУГОЇ НАЗВИ НЕ БУДЕ (рядок 4104; ЖИВІ-17 №11–13). Руки 3–4 пишуть
# «color #E6DCCD (warm oat)», «color #ffffff pure white», «Emerald velvet dress … in color #043d22», і код кольору
# давав другу назву: «колір білий чистий білий», «кольору білого (теплого вівсяного)», «Смарагдово-зелена … кольору
# хвойний» — правило «лиши її слово» тримав лише промпт шару, і п'ять разів не втримав. Тепер такий hex знімається
# без коду, і лишається її слово. Її слово — дужки одразу за hex або назва кольору внутрішньої мови (`color_name`:
# коди й останнє слово складених, синоніми написання) у тому ж реченні, що й hex; речення кінчається на «.», «!», «?»
# перед пробілом чи кінцем, або на новому рядку. Колір без назви («color #043d22 made from heavy fabric» без
# «emerald» у реченні, «color #059669, fabric: silk») іде кодом, як доти.
_СИНОНІМИ_КОЛЬОРУ = {"gray": "grey", "silver": "silvery", "gold": "golden", "pearl": "pearly", "ivory": "cream",
                     "charcoal": "graphite"}
_КІНЕЦЬ_РЕЧЕННЯ = re.compile(r"[.!?](?:\s|$)|\n")


def _слова_кольору():
    """Слова назв кольору внутрішньої мови: коди `color_name`, у складених («soft_pink») — лише останнє слово, назва
    кольору («pink»); «soft», «light», «denim» — прикметники й тканина («soft knit»), назвою кольору не є, а hex
    біля них без коду лишав річ без кольору (рядок 4280); та синоніми написання."""
    ч = set(_СИНОНІМИ_КОЛЬОРУ)
    for к in _ВМ.ТАБЛИЦЯ.get("color_name", {}):
        ч.add(к)
        ч.add(к.split("_")[-1])
    return ч


def _колір_названо(текст, поч, кін):
    """Чи hex у `текст[поч:кін]` має в тому ж реченні її власну назву кольору (див. вище)."""
    після, перед = текст[кін:], текст[:поч]
    дужки = re.match(r"\s*\(([^()\n]*)\)", після)
    if дужки and re.search(r"[^\W\d_]", дужки.group(1)):
        return True
    речення = _КІНЕЦЬ_РЕЧЕННЯ.split(перед)[-1] + " " + _КІНЕЦЬ_РЕЧЕННЯ.split(після)[0]
    слова = _слова_кольору()
    return any(т.lower() in слова for т in re.findall(r"[A-Za-z]+", речення))


def кольори_кодом(текст):
    """Текст із hex → той самий текст, де кожен hex (з ярликом і дужками) — «[colour: <код>]» або нічого.
    Hex, біля якого вже стоїть її назва кольору, знімається без коду (`_колір_названо`)."""
    def код(м):
        ярлик, дужки = м.group("ярлик") or "", м.group("дужки") or ""
        if _колір_названо(м.string, м.start("hx"), м.end("hx")):
            назва = (м.group(6) or "").strip()
            return назва if re.search(r"[^\W\d_]", назва) else ярлик + дужки
        к = _код_кольору(м.group(3) or м.group(4))
        return ярлик + ("[colour: %s]" % к if к else "") + дужки
    if not _HEX_У_ТЕКСТІ.search(str(текст or "")):
        return текст
    return re.sub(r"[ \t]{2,}", " ", _HEX_У_ТЕКСТІ.sub(код, str(текст or ""))).replace(" ,", ",")


def _абзац_кольорів(розмітка, коди_речей=()):
    """Абзац промпту про коди кольорів — лише вжиті коди (у текстах і біля речей переліку, `коди_речей`) з внутрішнім
    словом ядра; без них — ""."""
    у_текстах = {к for р in розмітка for к in _КОД_КОЛЬОРУ.findall(р["текст"])}
    коди = sorted(у_текстах | set(коди_речей))
    if not коди:
        return ""
    слова = "; ".join("%s — %s" % (к, _ВМ.ключ("color_name", к)) for к in коди) + ".\n\n"
    if not у_текстах:
        return "Colour codes: " + слова
    return ("[colour: код] у тексті — колір речі кодом: напиши на його місці українську назву цього кольору, "
            "узгоджену з реченням. Коли та сама річ у тексті вже має колір своїм словом, лиши її слово, а "
            "другої назви кольору не додавай. Коди: " + слова)


def розмітити(тексти, виправ=None):
    """[{н, ключ, текст}] з `тексти` ([{ключ, текст}] або {ключ: текст}): лише
    непорожні тексти з літерами, номери — з 1, у порядку входу. `виправ` — {ключ: [слова]}
    (ПРОЗА-1): текст ключа вже переклала модель, і в ньому лише ці слова не кирилицею — вони
    їдуть у промпт поруч із текстом (`виправ`), щоб повтор правив їх, а не перекладав усе."""
    пари = list(тексти.items()) if isinstance(тексти, dict) else \
        [(т.get("ключ"), т.get("текст")) for т in (тексти or []) if isinstance(т, dict)]
    вих = []
    for ключ, текст in пари:
        т = кольори_кодом(str(текст or "").strip()).strip()
        if not re.search(r"[^\W\d_]", т):
            continue
        р = dict(н=len(вих) + 1, ключ=str(ключ), текст=т)
        слова = [str(с) for с in ((виправ or {}).get(str(ключ)) or []) if str(с).strip()]
        if слова:
            р["виправ"] = list(dict.fromkeys(слова))
        вих.append(р)
    return вих


# ── РЕЧІ ОБРАЗУ — ПЕРЕЛІКОМ ІЗ НАЗВАМИ, ЯКІ ВОНА БАЧИТЬ НА КАРТЦІ (ПЕРЕКЛАД-34, рядок 4450; п.12) ────────────────
# ЩО БУЛО ВИДНО. Перекладачка бачила лише англійські тексти картки, а українських назв речей — ні, тож вид речі
# брала з англійського слова: «plimsolls», «red sneakers» → «еспадрильї» (на картці «Кеди червоні», Ж21 №13),
# «peep-toe ankle boots» → «Мокасинові … черевички» («Ботильйони замшеві мокко», Ж22 №7 рука 2), «grey wool coat»
# → «плащ» («Вовняне сіре пальто в клітинку», рука 1) — і рід та число теж вгадувала: «Темно-зелена шкіряна
# клатч», «тренувальний сліпони» (№8 рука 3, назва вигаданої речі в тому ж виклику). ЩО ТЕПЕР. Показ дає разом із
# текстами речі картки: номер і назву з крамниці, а вигаданої чи її речі з фото — ключ тексту, де ця назва
# перекладається в цьому ж виклику (`мовоюКарткуП`). Промпт називає кожну річ номером із назвою (назва вигаданої —
# «текст н=K») і просить вид — іменником назви, узгодження — з ним, а речей, яких англійський текст не називає, не
# додавати (рядок 4450). Назв код не читає: передає як є, слова пише мовна модель (п.12).
# ОПИС РЕЧІ — СВОЇМ ТЕКСТОМ, КОЛІР РЕЧІ — СЛОВОМ КРАМНИЦІ ЧИ КОДОМ (ПЕРЕКЛАД-36, рядки 4683, 4687, 4689; п.18, п.12).
# ЩО БУЛО ВИДНО. Опис руки 1–2 модель пише річ за річчю (`about_items` з номером речі), а показ віддавав шару одну
# прозу — абзаци без номера. Перекладачка мала перелік назв, але не знала, який абзац про яку річ, і вид та колір
# брала з англійських слів моделі про фото, бо правило так і казало («колір… перекладай з тексту»): «dark
# heather-grey knit» → «темно-фіолетовий светр» (у переліку «Джемпер … темно-сірий-молочний», ЖИВІ-24 07),
# «graphite headband» → «Поясна стрічка» (у переліку «Обруч Келлі…» і «Поясна сумка…», ЖИВІ-23 №13), «lime-green
# bag» → «лимонна» («Шкіряна сумка яскраво-зеленого кольору»), «pearl necklace» → «перлова намистина» («Намисто з
# 5 рядів перлин айворі»). ЩО ТЕПЕР. Абзац про річ іде своїм текстом, і перелік каже біля речі, який текст про
# неї («text н=M»); біля речі крамниці — код її кольору (`колір` картки — код каталогу, у вікні слова крамниці; без
# нього — hex тим самим вікном, що підписує палітру, `_код_кольору`). Колір речі — слово її назви (річ зберігає
# слово крамниці, п.18), а без нього — назва коду; кольорові слова англійського тексту про цю річ — враження моделі
# від фото, не її колір. Назв і слів код не читає: передає назву, номер тексту й код (п.12).
# ВИД РЕЧІ — КОДОМ (рядки 5820, 3782; п.12). ЩО БУЛО ВИДНО. Перелік давав назву, колір і номер тексту, а вид речі
# перекладачка брала з англійського слова моделі: «Suede pumps» → «Черевики з замші…» при «Туфлі човники» (живий
# 07 ПІСЛЯ #1083, картка руки 1), «Emerald green snakeskin boots» → «ботильйони» при чоботях до коліна (ЖИВІ-14 №11).
# ЩО ТЕПЕР. Біля речі крамниці стоїть код її виду (`item_type` укладки — той самий `type`, що бачила стилістка в
# `дріт_моделі.опис`; без типу — код слота, як «kind» там же), а правило каже: іменник речі в кожному тексті — цього
# виду. Слів код не читає: дає код.
ПРАВИЛО_РЕЧЕЙ = ("When a text speaks of an item of the list, call it by the kind in its name — the same noun in the "
                 "right case (list «Тренч бежевий подовжений» — text «тренч», «Светр в'язаний оверсайз» — «светр»), "
                 "not by another kind or a synonym of the English word. Make every adjective, pronoun and verb with "
                 "the item agree with that noun in gender and number («Тренч бежевий» — «бежевий тренч, який…»; "
                 "«Лофери шкіряні» — «шкіряні лофери, які…»). A name you translate in this same call (text н=K): "
                 "give it one noun and call the item by it, in agreement, in every text. A text the list gives as "
                 "about an item (about it: text н=M) speaks of that one item, and so does every other text where the "
                 "English names it. The colour of an item of the list is the colour of its name: keep the shop's "
                 "colour word from its name; when its name has no colour word, write the Ukrainian name of its colour "
                 "code. The English colour words for that item are the stylist's impression of a photo: do not turn "
                 "them into a colour of their own — the item's colour stands in their place. Colours of its details "
                 "(trim, strap, buttons, print), its fabric and the rest — translate from the text. The list is for "
                 "names only: an item the English text does not name is not added to the translation — neither to "
                 "the description nor to the advice. The kind code next to an item (kind code: …) is the code of "
                 "its kind: every noun for that item, in every text, names this kind and no other, whatever word "
                 "the English text uses; a code ending in _generic names only the family (dress_generic — a dress, "
                 "bag_generic — a bag). The kind noun of its name and this code are the same kind: write the name's "
                 "noun.")


def _код_кольору_речі(р):
    """Код кольору речі з переліку картки: `код_кольору` з каталогу, коли він код `color_name`, інакше hex тим
    самим вікном, що підписує палітру (`_код_кольору`), або None. Вигадана й її річ коду тут не мають: їхній колір —
    у тексті, який перекладає цей самий виклик."""
    if р.get("ключ"):
        return None
    к = str(р.get("код_кольору") or "").strip()
    if к in _ВМ.ТАБЛИЦЯ.get("color_name", {}) and not _ВМ.невідомо(к):
        return к
    hx = re.fullmatch(r"#?([0-9a-fA-F]{6})", str(р.get("hex") or "").strip())
    return _код_кольору(hx.group(1)) if hx else None


# НОВА РІЧ ЗМІНИ (рядок 6459, картка «Оціни образ»). Під текстом «Що змінити» жінка бачить річ зміни, а перекладачка
# її не знала: «взуття SAFARI» → «лофери» над «Чоботи SAFARI замшеві» (живі 1016-1, Ж:03), «Black ankle boots» запасних
# → «лофери» (6б Ж:08). Тепер біля такої речі стоїть посилання на текст її зміни (`заміна` — ключ тексту), а правило
# каже: нова річ у тому тексті — ця, її виду й кольору; її власна річ, яку зміна міняє, лишається своєю. Речення стоїть
# лише в промпті з такою річчю: картки рук його не бачать (кеш їхнього початку той самий).
ПРАВИЛО_НОВОЇ_РЕЧІ = (" An item given as the new item of a text (new item of text н=M) is what that text advises "
                      "her to take in place of her own item: wherever that text speaks of the new thing, it is this "
                      "item, of its kind and its colour, whatever the English text says; her own item there keeps its "
                      "own name.")


def _абзац_речей(розмітка, речі):
    """(абзац промпту з речами картки, коди кольорів речей). `речі` — [{н, назва, ключ?, опис?, заміна?, тип?, колір?,
    hex?}] з
    показу (`тип` — ключ ядра `item_type` з укладки речі, без нього `слот`; у промпт — кодом виду):
    номер і назва біля речі; назва, яку перекладає цей самий виклик (`ключ` є в `розмітка`), — посиланням «текст н=K»;
    текст про цю річ (`опис` — ключ тексту в `розмітка`) — «about it: text н=M»; текст зміни, чия це нова річ
    (`заміна`), — «new item of text н=M» з `ПРАВИЛО_НОВОЇ_РЕЧІ`; код кольору речі крамниці
    (`_код_кольору_речі`). Без речей — ("", [])."""
    н_ключа = {р["ключ"]: р["н"] for р in розмітка}
    рядки, коди, нові = [], [], False
    for р in речі if isinstance(речі, list) else []:
        if not isinstance(р, dict):
            continue
        н, назва = н_ключа.get(str(р.get("ключ") or "")), " ".join(str(р.get("назва") or "").split())
        if not (н or назва):
            continue
        к, про = _код_кольору_речі(р), н_ключа.get(str(р.get("опис") or ""))
        заміна = н_ключа.get(str(р.get("заміна") or ""))
        нові = нові or bool(заміна)
        вид = ((_ВМ.код("item_type", р.get("тип")) if р.get("тип") else None)
               or (_ВМ.код("slot", р.get("слот")) if р.get("слот") else None))
        if к:
            коди.append(к)
        рядки.append("%s — %s" % (р.get("н") or len(рядки) + 1, "назва в тексті н=%d" % н if н else назва)
                     + (" · kind code: %s" % вид if вид else "")
                     + (" · colour code: %s" % к if к else "") + (" · about it: text н=%d" % про if про else "")
                     + (" · new item of text н=%d" % заміна if заміна else ""))
    if not рядки:
        return "", []
    return ("Речі образу — перелік, який жінка бачить на картці (номер речі — назва біля неї):\n"
            + "\n".join(рядки) + "\n" + ПРАВИЛО_РЕЧЕЙ + (ПРАВИЛО_НОВОЇ_РЕЧІ if нові else "") + "\n\n"), коди


def промпт(розмітка, речі=None):
    """Промпт моделі шару: роль і форма (з речами картки й кодами кольорів, коли вони є) + JSON-мапа текстів
    «н → текст» тієї самої форми, що відповідь (рядок 6752), по одному на рядок. `РЕЧЕННЯ_ВИПРАВ` стоїть за `ВХІД_ВИХОДУ` лише тоді, коли в розмітці є `виправ` (рядок 6197)."""
    основа, _, хвіст = ПРОМПТ_ВИХОДУ.rpartition("ТЕКСТИ:\n")
    if any(р.get("виправ") for р in розмітка):
        основа = основа.replace(ВХІД_ВИХОДУ, ВХІД_ВИХОДУ + РЕЧЕННЯ_ВИПРАВ, 1)
    абзац, коди = _абзац_речей(розмітка, речі)
    return основа + абзац + _абзац_кольорів(розмітка, коди) + "ТЕКСТИ:\n" + хвіст + "{\n" + ",\n".join(
        "%s: %s" % (_json_.dumps(str(р["н"])), _json_.dumps(dict(текст=р["текст"], виправ=р["виправ"]) if р.get("виправ")
                                                           else р["текст"], ensure_ascii=False)) for р in розмітка) + "\n}"


_ЛАПКИ_КРАЇ = (("«", "»"), ('"', '"'), ("“", "”"))


def _без_обгортки(вихід, вхід):
    """Текст моделі без лапок навколо ВСЬОГО тексту, яких не було у вході."""
    т = str(вихід or "").strip()
    for л, п in _ЛАПКИ_КРАЇ:
        if len(т) > 1 and т.startswith(л) and т.endswith(п) and not str(вхід).strip().startswith(л):
            return т[len(л):-len(п)].strip()
    return т


# «▁» (U+2581, SentencePiece) Lapa ставить у власну відповідь замість пробілів, зокрема відступом
# перед ключами, і ламає ним JSON (Н-1, 26.09: той самий прийом, що `каталог_розбір.ВСТАВКА`, і
# лише так вимір ноутбука мірив зміст, а не токенізатор). Тут вона стає пробілом: поза рядком
# JSON це відступ, у рядку — пробіл між її словами (уривок звіряється без зайвих пробілів).
_ВСТАВКА = "▁"


# НЕДІЙСНИЙ ЕКРАН У РЯДКУ JSON (П-3; Н-1, 26.09, MamayLM, картка руки 3): модель написала
# «\н» — кириличну «н» на місці «n» екрана переводу рядка, — і вся відповідь не розбиралась:
# п'ять перекладених текстів картки лишились внутрішньою мовою. «\н» — це «\n»; перед
# іншим знаком, який не є екраном JSON, зворотна риска знімається. Пари «\\» регулярка
# бере цілими, тож буквальна риска перед «н» лишається рискою.
_ЕКРАН = re.compile(r"\\(.)", re.S)


def _екрани(т):
    """Текст відповіді з недійсними екранами JSON, полагодженими так, як сказано вище."""
    return _ЕКРАН.sub(lambda м: "\\n" if м.group(1) == "н"
                      else м.group(0) if м.group(1) in '"\\/bfnrtu' else м.group(1), т)


def _обʼєкт(відповідь, нотатки=None):
    """(JSON-об'єкт або масив із відповіді моделі, причина, коли не вийшло).

    Недійсний екран лагодиться (`_екрани`), лише коли суворий розбір не вдався; що так
    прочитано, дописується в `нотатки`, коли їх дали, — у запис виклику шару, не мовчки."""
    сир = str(відповідь or "").replace(_ВСТАВКА, " ")      # «▁» Lapa — пробіл (М-2)
    if нотатки is None:
        об, чому_не, _ = _ПР.розбір_останній(сир, ())
    else:
        об, чому_не = _ПР.розбір(сир)
    if об is None and _екрани(сир) != сир:
        об, _ = _ПР.розбір(_екрани(сир))
        if об is not None:
            сир = _екрани(сир)
            if нотатки is not None:
                нотатки.append("invalid_escape_read")
    if об is None:                  # `протокол.розбір` бере лише об'єкт; масив дочитується тут
        for т in dict.fromkeys((сир, _екрани(сир))):
            try:
                об = _json_.loads(re.sub(r"^```(?:json)?\s*|\s*```$", "", т.strip()))
                break
            except ValueError:
                об = None
    if нотатки is not None and (об is None or (isinstance(об, dict) and "```" in сир)):
        # лише там, де прочитане названо в записі; з огорожами суворий розбір бере ПЕРШУ версію
        for т in dict.fromkeys((сир, _екрани(сир))):
            злите, скільки = _обʼєкти_злито(т)
            if злите is not None and (об is None or скільки > 1):
                об = злите
                нотатки.append(КІЛЬКА_ОБʼЄКТІВ)
                break
    return об, чому_не


# ВІДПОВІДЬ ІЗ КІЛЬКОМА JSON-ОБ'ЄКТАМИ — ЗЛИВАЮТЬСЯ ПО ПОРЯДКУ, ПІЗНІШИЙ КЛЮЧ ПЕРЕКРИВАЄ (ПРОЗА-1, 02.10.2026,
# рядки 970, 925, 976).
# ЩО БУЛО ВИДНО. Живий стенд ПЕР-536 (ZHYVA=sonnet, сід 3): картка руки 1 «Без пояснення словами» у
# 3 з 6 сцен (робота, похорон, театр). Сира відповідь шару в усіх трьох і на повторі — та сама форма:
# повний український JSON, далі рядок «Wait — I must correct that: the output above contains
# mixed-alphabet words…» і ВИПРАВЛЕНИЙ JSON. Модель сама впіймала «баскa»/«structурована» (заборону
# з промпту, ВМ-3в) і переписала. Співбесіда того ж прогону — інша форма того самого: сім об'єктів
# по одному тексту, потім усі сім разом; «код не знає» — «Wait — the output must include item 13» і
# другий об'єкт. `протокол.розбір` бачив «Extra data: line 3», зріз «від першої { до останньої }»
# об'єктів не ділить: усі тексти лишались вхідними (англійськими), П-3 знімав опис і «Як це
# носити», хоча у відповіді лежали готові переклади.
# ЩО ТЕПЕР. Коли суворий розбір не вдався, відповідь читається як послідовність JSON-об'єктів, що
# стоять з початку рядка; вони зливаються по порядку, і ключ пізнішого перекриває той самий ключ
# ранішого — останнє слово моделі про кожен текст: повне виправлення дає рівно другий об'єкт,
# часткове («лише 13») не губить решти першого. Що так прочитано, каже нотатка
# `several_json_merged` у записі шару, сира відповідь — поруч; тому так читають лише виклики з
# `нотатки` (тексти картки, повідомлення), не мовчки. Обидві версії в огорожах ```json — та сама
# форма, але там суворий розбір не падає, а мовчки бере ПЕРШУ (невиправлену): `_У_ДУЖКАХ` знаходить
# першу огорожу. Тому з огорожами і кількома об'єктами злиття діє й після вдалого суворого розбору.
КІЛЬКА_ОБʼЄКТІВ = "several_json_merged"
_ПОЧАТОК_ОБʼЄКТА = re.compile(r"(?m)^[ \t]*(?:```(?:json)?[ \t]*\n[ \t]*)?\{")


def _обʼєкти_злито(т):
    """(цілі JSON-об'єкти з початку рядка, злиті по порядку — пізніший ключ перекриває, або None;
    скільки їх)."""
    декодер, кінець, злите, скільки = _json_.JSONDecoder(), 0, None, 0
    for м in _ПОЧАТОК_ОБʼЄКТА.finditer(т):
        п = м.end() - 1
        if п < кінець:                      # вкладений у вже прочитаний об'єкт
            continue
        try:
            об, кінець = декодер.raw_decode(т, п)
        except ValueError:
            continue
        if isinstance(об, dict):
            злите, скільки = dict(злите or {}, **об), скільки + 1
    return злите, скільки


# ПРИЧИНИ Й НОТАТКИ ШАРУ — КОДАМИ (рядок 168, аудит/ПРОДУКТ.md п.12). Доти тут стояли речення коду («текст у полі
# вхідної форми … прочитано», «відповідь не JSON (…)», «модель не повернула текстів: 2 з 6»), і вони їхали
# в запис виклику й діагноз звіту власника. Тепер — коди, а після двокрапки лише сирі дані (текст помилки
# розбору, числа): `input_form_read` — текст знайдено у вхідній формі {н, текст}/{n, text};
# `invalid_escape_read` — недійсний екран «\н» прочитано як «\n»; `not_json: <чому>` — відповідь не JSON;
# `not_json_object: <чому>` — не JSON-об'єкт (`<чому>` — код `протокол.розбір`: `empty_answer`,
# `no_json_object(prose)`, `invalid_json(line=L,col=C)`, `json_not_object(<тип>)`); `texts_missing: N/M` — N текстів із M без відповіді;
# `no_text_field` — нема поля `text`; `text_unknown: <значення>` — `text` каже «невідомо».
ФОРМА_ВХОДУ = "input_form_read"


def _з_форми(x):
    """Обʼєкт вхідної форми {н, текст} → (н, текст); ключі text/переклад/translation теж: MamayLM
    26.09 повернула на кожен номер {"n": 1, "text": "…"} (П-3), і шість перекладів картки
    лишались внутрішньою мовою. Не та форма — (None, None)."""
    if not isinstance(x, dict):
        return None, None
    н = next((x[к] for к in ("н", "n") if к in x), None)
    return н, next((x[к] for к in ("текст", "text", "переклад", "translation")
                    if isinstance(x.get(к), str)), None)


# КІЛЬКА ОБ'ЄКТІВ ВХІДНОЇ ФОРМИ — ВСІ ТЕКСТИ, А НЕ ПЕРШИЙ (рядок 5983; ОЦІНКА-ЖИВИЙ-15, qwen). Перекладачка картки
# оцінки відповідала {"н": 1, "текст": "…"}, {"н": 2, "текст": "…"} — об'єктами через кому без [] — або одним
# об'єктом, де пари «н»/«текст» ідуть одна за одною. Розбір брав перший об'єкт (чи останню пару), і решта текстів
# лишалась вхідною: 18 викликів сцен 01–10 губили по 1–4 тексти (38 із 193 текстів живого 15), а вхідний текст оцінки — на «ви» («Ваша біла
# футболка», хоча переклад дав «Твоя»). Тепер пари читаються по порядку з усіх об'єктів відповіді.
_КЛЮЧІ_НОМЕРА, _КЛЮЧІ_ТЕКСТУ = ("н", "n"), ("текст", "text", "переклад", "translation")


# ПАРИ БЕЗ СВОЇХ «{» (рядок 6020; живий 15, qwen, `02_…/seed2_03`, `05_…/seed5_03`, `06_…/seed1_03`, `10_…/seed5_03`).
# Перекладачка картки оцінки відповідала `{"н": 1, "текст": "…"},` і далі `"н": 2, "текст": "…"},` — одна «{» на
# початку й зайва «}» після кожної пари. Об'єктом читалась лише перша пара, решта текстів (назви речей) лишались
# англійськими: 8 текстів на чотирьох записах. Тепер пари читаються й підряд, з самої форми «номер, потім текст»:
# ключ номера, за ним ключ тексту й JSON-рядок; береться прочитання, що дало більше пар. Слів код не читає.
_ПАРА_ПІДРЯД = re.compile(r'"(?:%s)"\s*:\s*"?(\d+)"?\s*,\s*"(?:%s)"\s*:\s*(?=")'
                          % ("|".join(_КЛЮЧІ_НОМЕРА), "|".join(_КЛЮЧІ_ТЕКСТУ)))


def _пари_підряд(т):
    """{н: текст} з пар «номер, текст», що стоять підряд у тексті відповіді, хоч би які дужки між ними; або {}."""
    пари, п, декодер = {}, 0, _json_.JSONDecoder()
    while True:
        м = _ПАРА_ПІДРЯД.search(т, п)
        if not м:
            return пари
        try:
            текст, п = декодер.raw_decode(т, м.end())
        except ValueError:
            п = м.end()
            continue
        if isinstance(текст, str):
            пари[м.group(1)] = текст


def _пари_вхідної_форми(відповідь):
    """{н: текст} з усіх пар «н»/«текст» відповіді — по порядку, у скількох завгодно об'єктах або підряд без
    своїх дужок (`_пари_підряд`); або {}."""
    сир = str(відповідь or "").replace(_ВСТАВКА, " ")
    декодер = _json_.JSONDecoder(object_pairs_hook=list)
    for т in dict.fromkeys((сир, _екрани(сир))):
        пари, п = {}, т.find("{")
        while п >= 0:
            try:
                кв, кінець = декодер.raw_decode(т, п)
            except ValueError:
                п = т.find("{", п + 1)
                continue
            н = None
            for к, в in кв:
                if к in _КЛЮЧІ_НОМЕРА:
                    н = в
                elif к in _КЛЮЧІ_ТЕКСТУ and isinstance(в, str) and н is not None:
                    пари[str(н)], н = в, None
            п = т.find("{", кінець)
        підряд = _пари_підряд(т)
        if len(підряд) > len(пари):
            пари = підряд
        if пари:
            return пари
    return {}


def _розгорнути_номери(об, нотатки):
    """Розгортає єдину номерну обгортку, зберігаючи власний текст під її номером.

    У прогоні В (5301) усі інші тексти вкладено в перший. Читаємо лише явні номери:
    номер самої обгортки не дублюється всередині. Мапу з кількома верхніми номерами
    не розгортаємо: вкладені номери в ній можуть означати речі, а не тексти."""
    if not isinstance(об, dict) or len(об) != 1:
        return об
    н, значення = next(iter(об.items()))
    if not str(н).isascii() or not str(н).isdigit() or not isinstance(значення, dict):
        return об
    вкладені = {к: в for к, в in значення.items() if str(к).isascii() and str(к).isdigit()}
    if not вкладені or н in вкладені:
        return об
    нотатки.append("numbered_wrapper_read")
    return dict(об, **вкладені)


# ПЕРЕКЛАД, КОРОТШИЙ ЗА ДЖЕРЕЛО, — НЕ ВІДПОВІДЬ (ОПИС-1, рядок 1426). Шар урізав прозу, і
# картка йшла без пояснення: «Чому цей образ» 493 знаки, описано 3 речі з 6 (ж8_зима р1),
# опис, що обривається «зі структурованої...» (ж4_робота_живіт р3), — 3 картки / 3 прогони
# 02.10, а повтор `виправ` повертав той самий урізаний текст, і його приймали. Українська
# проза довша за англійську, тож переклад, коротший за 60 % джерела, — урізаний, а не
# стислий; так само текст, що закінчується трьома крапками, коли джерело ними не
# закінчується. Короткі тексти (назва речі, «Blazer» → «Жакет») не судяться: межа — від
# `_МІН_ДЖЕРЕЛА` знаків. Урізаний переклад стоїть у `без_відповіді` (повтор), а сам він — у
# `короткі`: коли й повтор урізаний, показ бере довший із двох, а не англійське джерело.
_ЧАСТКА_ДОВЖИНИ = 0.6
_МІН_ДЖЕРЕЛА = 160
_ОБРИВ = re.compile(r"(?:\.\.\.|…)\s*$")


def _урізано(вихід, джерело):
    """Переклад `вихід` урізаний проти `джерело` (див. вище) → код причини або None."""
    д, в = str(джерело or "").strip(), str(вихід or "").strip()
    if len(д) < _МІН_ДЖЕРЕЛА:
        return None
    if len(в) < _ЧАСТКА_ДОВЖИНИ * len(д):
        return "shorter_than_source"
    if _ОБРИВ.search(в) and not _ОБРИВ.search(д):
        return "ends_cut"
    return None


ПОЛЯ_ЗЛИТО = "fields_joined"


def _лише_рядки(x):
    """Обʼєкт, усі значення якого — непорожні рядки, а ключі — не номери текстів (тоді це поля одного тексту)."""
    return (isinstance(x, dict) and bool(x) and all(isinstance(в, str) and в.strip() for в in x.values())
            and not any(str(к).isascii() and str(к).isdigit() for к in x))


def прийняти(розмітка, відповідь):
    """Відповідь моделі шару → dict(тексти={ключ: текст}, без_відповіді=[ключі], причина,
    нотатки=[що прочитано з неідеальної форми], короткі={ключ: урізаний переклад}).

    Кожен текст, який модель повернула, стає тим, що бачить жінка. Текст, якого вона не
    повернула (відповідь не JSON, номера нема, значення порожнє) або повернула урізаним
    (`_урізано`, рядок 1426), лишається вхідним і стоїть у `без_відповіді` з причиною —
    мовчки не губиться нічого."""
    нотатки = []
    об, чому_не = _обʼєкт(відповідь, нотатки)
    # ОДИН ОБ'ЄКТ ВХІДНОЇ ФОРМИ ЗАМІСТЬ МАПИ (рядок 2812): живий П1 — MamayLM на шість текстів картки
    # руки 1 відповіла самим {"н": 1, "текст": "<опис українською>"}; ключа «1» не було, тож
    # `texts_missing: 6/6`, а повтор того самого промпта дав ту саму відповідь — «Чому цей образ»
    # пішов без пояснення. Це той самий масив {н, текст} з одного елемента.
    if isinstance(об, dict) and all(None is not з for з in _з_форми(об)) \
            and not any(str(р["н"]) in об for р in розмітка or []):
        об = _пари_вхідної_форми(відповідь) or [об]
        нотатки.append(ФОРМА_ВХОДУ)
    # МАСИВ ЗАМІСТЬ ОБ'ЄКТА — та сама відповідь іншою формою: рядки в порядку текстів або
    # {н, текст}. Читається, лише коли однозначно (рядків рівно стільки, скільки текстів)
    if isinstance(об, list):
        пари = [_з_форми(x) for x in об]
        if all(н is not None for н, _ in пари):
            об = {str(н): т for н, т in пари}
        elif len(об) <= len(розмітка or []) and all(isinstance(x, str) for x in об):
            об = {str(р["н"]): x for р, x in zip(розмітка, об)}
    об = _розгорнути_номери(об, нотатки)
    тексти, без, короткі, урізані = {}, [], {}, []
    for р in розмітка or []:
        вих = об.get(str(р["н"])) if isinstance(об, dict) else None
        if isinstance(вих, dict) and _з_форми(вих)[1] is not None:
            вих = _з_форми(вих)[1]
            if ФОРМА_ВХОДУ not in нотатки:
                нотатки.append(ФОРМА_ВХОДУ)
        elif _лише_рядки(вих):
            # ТЕКСТ ПОЛЯМИ (рядок 6021; MamayLM, `13_ж2_йога_зранку/seed3_18`): {"1": {"<поле>": "…", "<поле>": "…"}} —
            # переклад тексту, розкладений на поля з назвами, які придумала модель (опис і порада окремо). Назв полів
            # код не читає: значення йдуть по порядку абзацами — так, як абзаци стояли в джерелі.
            вих = "\n\n".join(в.strip() for в in вих.values())
            if ПОЛЯ_ЗЛИТО not in нотатки:
                нотатки.append(ПОЛЯ_ЗЛИТО)
        if isinstance(вих, (list, tuple)):
            вих = " ".join(str(x) for x in вих)
        if isinstance(вих, str) and not _ВМ.невідомо(вих):   # "null" / "None" — не текст для неї
            т = _без_обгортки(вих, р["текст"])
            чому_коротко = _урізано(т, р["текст"])
            if чому_коротко and т.strip():
                короткі[р["ключ"]] = т
                урізані.append("%s:%s" % (р["ключ"], чому_коротко))
                тексти[р["ключ"]] = р["текст"]
                без.append(р["ключ"])
            else:
                тексти[р["ключ"]] = т
        else:
            тексти[р["ключ"]] = р["текст"]
            без.append(р["ключ"])
    причина = None
    if без:
        причина = ("not_json: %s" % чому_не if not isinstance(об, dict)
                   else "texts_missing: %d/%d" % (len(без) - len(урізані), len(розмітка or [])))
        if урізані:
            причина = ("%s; " % причина if len(без) > len(урізані) else "") + "cut: " + ", ".join(урізані)
    return dict(тексти=тексти, без_відповіді=без, причина=причина, нотатки=нотатки,
                **({"короткі": короткі} if короткі else {}))


