_БЕЗ_У_РОЗМОВІ = ("quotes", "question_about")    # пари несуть цитату самі; про що питання — `need`


def _тип_en(с):
    """`_тип` англійською: яке значення чекає поле (коди, число, рядок її мовою, об'єкт, список)."""
    if "enum" in с:
        return "codes: " + ", ".join(к for к in с["enum"] if к != U)
    if _ref(с) == "free_text":
        return "a string in her language"
    if с.get("type") == "array":
        return "list" + (" (up to %d)" % с["maxItems"] if с.get("maxItems") else "") + " of " \
            + _тип_en(с.get("items") or {})
    if с.get("type") == "object" and с.get("properties"):
        return "{" + "; ".join("%s — %s" % (к, _тип_en(v)) for к, v in с["properties"].items()) + "}"
    if с.get("type") in ("number", "integer"):
        межі = [x for x in (с.get("minimum"), с.get("maximum")) if x is not None]
        return ("integer" if с["type"] == "integer" else "number") + (" %s–%s" % tuple(межі) if len(межі) == 2 else "")
    if с.get("type") == "string":
        return "string" + (" #rrggbb" if "#" in str(с.get("pattern") or "") else "")
    if "oneOf" in с:
        return " or ".join(_тип_en(в) for в in с["oneOf"] if в.get("const") != U)
    return "value"


def _ознаки_речі_en():
    """Рядки ознак речі «  · <ознака> — <що>; <коди>» — один опис речі для ходу розмови й перекладачок входу
    (`_РЕЧІ_EN`; вид речі — з підписами, `_типи_речей`)."""
    return ["  · %s — %s; %s" % (к, _РЕЧІ_EN[к], ("codes: " + _типи_речей()[len("коди: "):])
                                 if к == "item_type" else _тип_en(с))
            for к, с in _ВМ.РІЧ_У_СЛОВАХ.items() if к != "quote"]


# Оголошення перекладачок входу поза розмовою (рядок 6191) — тут, бо їхні коди читають `_РЕЧІ_EN` і `_тип_en` вище.
ОГОЛОШЕННЯ_ВХОДУ = {вид: _оголошення_входу(вид) for вид, в in ВИДИ_ВХОДУ.items() if "скелет" in в}


def _довідник_en(поле):
    """«codes: <код> (<підпис плитки>[: <нота>]), …» — `_коди_довідника` англійською рамкою."""
    return "codes: " + _коди_довідника(поле)[len("коди: "):]


def _коди_полем(поле, ключі):
    """«код | код …» — внутрішні ключі переліку `поле` його кодами."""
    return " | ".join(к for к in (_ВМ.код(поле, x) for x in ключі) if к)


# СЦЕНИ УМОВ ПОРАДИ (МОВА-ХІД-ТОНШЕ, рядок 3491): «вечірня сцена» стояла в умовах `goal` і `makeup` двічі слово в
# слово, «надворі» — в `movement` і `temperature`; тепер кожна визначена раз рядком словника, умови її називають.
def _сцени_умов():
    """{назва сцени: коли вона є} — ті самі множини, що `паспорт_нагоди.порада_коду`."""
    import паспорт_нагоди as _ПН
    return {"an evening scene": "hour 18 or later, or occasion %s, or place %s, or activity photoshoot" % (
                _коди_полем("occasion", _ПН._ВЕЧІРНІ_НАГОДИ), _коди_полем("place", _ПН._ВЕЧІРНІ_МІСЦЯ)),
            "outdoors": "setting outdoor or mixed, or place %s" % _коди_полем("place", _ПН._ПРОСТО_НЕБА_МІСЦЯ)}


