def _коди_норми():
    """Рядки кодів полів без цитати — від `formality` (якорі, смуги дрес-кодів) до `minute`: спільні для ходу
    розмови (`_коди_розмови`) і ходу плиток (`ХІД_ПЛИТОК`, рядок 6185), щоб словник норми події був один."""
    р = ["- formality — %s; without quote" % _ПОЛЯ_EN["formality"],
         "  · anchors — usual bands of events (examples for the band only, not codes): %s" % _смуги_місць_en(),
         "  · dress-code bands: %s" % _смуги_дрес_кодів_en()]
    # МОВА-1 (02.10): `part_of_day` — службове, як ці два, але доти його рядка тут не було: модель не
    # бачила ні опису, ні кодів, і «вдень», «по обіді», «на обід» без години губились (проба
    # `мова1_нечіткі.py`: 0 з 5 таких випадків).
    # `minute` (рядки 933/1135) — службове так само: стоїть при `hour`, цитати не потребує, бо без години
    # з її слів шов його не бере (`паспорт_з_шару`).
    for ім in ("reserved_colour", "open_zones", "part_of_day", "minute"):
        опис = _ПОЛЯ_EN[ім] % _місця_вечірні_en() if ім == "part_of_day" else _ПОЛЯ_EN[ім]
        р.append("- %s — %s; %s; without quote" % (ім, опис, _тип_en(_ВМ.СЦЕНАРІЙ[ім])))
    return р


def _коди_розмови():
    """Словник кодів ходу розмови — СТАЛИЙ (іде в кешований початок промпта): поля сценарію з
    формою значення, ознаки речі, теми поради з умовою, обовʼязкові питання, коди `need`."""
    import паспорт_нагоди as _ПН_
    поля = {ім: с for ім, с in _ВМ.СЦЕНАРІЙ.items() if ім not in _БЕЗ_У_РОЗМОВІ}
    # Рядок 3165 (живі 12, А/07): «"quote": "\"йога…\", \"value\": "everyday"» — цитата в екранованих лапках
    # ламала JSON, хід ішов шляхом main (виклик 0), і нагода губилась; промпт сам несе лапки екранованими
    р = ["Fields with a code or a number — each is a JSON object {\"quote\": the fragment of her words "
         "it stands on, copied letter for letter, \"value\": its value}; \"quote\" is a plain JSON string of "
         "her letters, with no quotation marks or backslashes of its own around them:"]
    for ім, с in поля.items():
        if _група(ім, с) == "пари":
            тип = _довідник_en(ім) if ім in _ГРУПИ_ДОВІДНИКА else _тип_en(с)
            if с.get("type") == "array" and "enum" in (с.get("items") or {}):
                тип += '; {"quote": the fragment of her words, "value": [codes]}'
            р.append("- %s — %s; %s" % (ім, _ПОЛЯ_EN[ім], тип))
            # Рядки 238 і 474: підвид офісу — лише за її словами; не названо — загальний `office` (ОФІС-1)
            if ім == "place":
                р += ["  · %s — kinds of one place, %s: one of them only when her words say which kind; "
                      "her words name only the %s — %s" % (" | ".join(коди), рід, рід,
                                                          рід if _ВМ.ключ("place", рід) else "no place")
                      for рід, коди in _ПН_.МІСЦЯ_ПІДВИДИ.items()]
        # Рядок 3317 (живі 12, Б/10): «відпустка на морі, пляж удень і вечеря на набережній» → `celebration`:
        # опис кодів не розводив свято й відпочинок; тепер їх розведено родом події (п.14, п.17: тлумачить модель)
        # Рядки 6187, 6188: «подорож лишається подорожжю» стояло ще в R7 — тепер лише тут; «Новий рік» (свято сцен) — родом
        if ім == "occasion":
            р.append("  · travel — she is away on a trip or a holiday, and every outing of it, by day or in the "
                     "evening, is travel; celebration — a festive event itself: a party, a birthday, an "
                     "anniversary, a festive day. A trip or a holiday without such an event is never celebration")
            # Рядок 5313 (ЖИВІ-1510-Г, Г2): «Весілля подруги в суботу» → celebration, і правила гості весілля
            # (`case.reserved_colour`) не мали звідки взятись; рід «свято» про весілля мовчав
            # Рядок 6090: «never celebration» — тепер в описі самої нагоди, куди модель дивиться
            р.append("  · wedding_guest — someone else's wedding, she is a guest (wedding_day when her words say it "
                     "is by day)")
            # Рядок 4622: спорт рухом і спорт нагодою — незалежні канали.
            # Модель називає рід обраної частини через occasion_part; код судить цю пару.
            # Рядок 6187: «спорт деінде в дні — movement sport» — дослівно опис `movement`; тут лише нагода
            р.append("  · sport — only when this outfit is for doing the sport (occasion_part sport); otherwise "
                     "occasion is the kind of the selected part, never sport")
    р.append("Items — lists of objects; every item she names goes into one of them, none is left out; each "
             "object has \"quote\" — the fragment of her words about this item, copied letter for letter — and "
             "only the attributes she named:")
    for ім in _РЕЧІ_З_ЦИТАТОЮ:
        if ім != "own_items":
            р.append("- %s — %s" % (ім, _ПОЛЯ_EN[ім]))
    р += _ознаки_речі_en()
    # Рядок 3310 (живі 12, Б/01–03): «одягну своє взуття з фото» — 3 з 3 сідів поле `shoes{…}` поза переліком із
    # вигаданими `ankle_boots, black` (на фото — біла сандаля): поле її речей одне, ознаки речі з фото — лише її слова
    # МОВА-ХІД-ТОНШЕ (рядок 3491): «лише ознаки з її слів» стояло тричі — в описі поля, у формі й у реченні про
    # фото; тепер раз, з фото поруч.
    р.append("- own_items — %s: objects with quote, name — the item in her words, status — %s, and only the "
             "attributes her words name (not zone or feature), also for an item in her photo: the photo is looked "
             "at by another model. It is the only field for her items: there is no field per part of the look"
             % (_ПОЛЯ_EN["own_items"], _тип_en(_ВМ.ЇЇ_РІЧ["status"])[len("codes: "):].replace(", ", " | ")))
    р.append("Fields in her words — a string in her language, without quote:")
    for ім, с in поля.items():
        if _група(ім, с) == "вільні":
            р.append("- %s — %s%s" % (ім, _ПОЛЯ_EN[ім], "; " + _тип_en(с) if с.get("type") == "array" else ""))
    р += _коди_норми()
    р.append("Advice topics — code: what to invite her to tell · when the topic applies (after your "
             "update, and only while the passport does not know it; for \"advice_topics\" the code has "
             "already checked it):")
    р += ["  · %s — %s" % (сцена, коли) for сцена, коли in _сцени_умов().items()]
    р += ["- %s: %s · %s" % (к, про, коли) for к, (про, коли) in _умови_тем().items()]
    р.append("Required questions — code: what to ask · when it applies (after your update):")
    р += ["- %s: %s · %s" % (к, що, коли) for к, (що, коли) in _ОБОВʼЯЗКОВЕ_EN.items()]
    р.append("need — who answers her this turn:")
    р += ["- %s — %s" % (к, о) for к, о in _ПОТРЕБИ_EN.items()]
    return tuple(р)


# Два правила спільні з ремонтом поради (`ПОРАДА`, рядок 3930): та сама форма звертання й ті самі межі теми.
# Рядок 6570 (ЖИВІ-1016-1 Ж:19, 20, 23): «йдете… не бажаєте показувати», «Ви йдете», «Ви… хочете» — «ви» в 3 з 35
# бульбашок; правило стояло з повним `ЗВЕРТАННЯ`, де антиприклад «ніколи «ви» (…хочете…, розкажіть…)» — і «хочете»,
# «розкажіть» MamayLM узяла саме звідти (у `invite` того ж ходу Ж:19 — «розкажіть»). Тепер форми лише «ти»
# (`ЗВЕРТАННЯ_ТИ`), як у перекладачок виходу (рядок 6195); «never the polite plural» каже межа `для_неї`.
_ПРАВИЛО_ФОРМИ = (
    "\"text\", \"invite\" and \"ask\" are natural literary Ukrainian: every Ukrainian word in Ukrainian "
    "Cyrillic letters only, each the letter itself (never a Unicode escape code), with no Latin letter inside "
    "it; brand and shop names as she wrote them. They "
    "speak to her as " + _ЗВЕРТАННЯ_ТИ + ".")
_ПРАВИЛО_ПРОФІЛЮ = (
    "Never ask her what suits her face (metal, white, neutrals): that is her profile. About jewellery — "
    "only which jewellery she wants with this look. Never ask how she usually dresses, her habits, her "
    "wardrobe or her taste in general: that is her profile too. An invitation is only about THIS outing and "
    "THIS look, and the \"register\" topic asks which style she wants for this look.")


