    # Шов доливає дельту поверх паспорта досі (`паспорт_з_шару`); `retract` знімає бажання й межі.
    # МОВА-ХІД-ПОЛЯ (рядки 3451, 3453, 3456, живі 13): перший хід MamayLM клав на фразу одне поле — «мінус
