# ── ПАСПОРТ І ПЛИТКИ КОДАМИ: МОДЕЛЬ БАЧИТЬ ТЕ, ЩО ЗНАЄ КОД, ЙОГО Ж МОВОЮ ──────────────────
def _паспорт_прості():
    """((ключ паспорта, перелік), …) — прості поля паспорта для моделі розмови, у порядку ключів промпта.

    ОДНА ВІДПОВІДНІСТЬ НА СИСТЕМУ (рядок 279, НГ-4): доти тут стояв другий примірник таблиці
    `паспорт_нагоди.ПОЛЕ_ВИМІРУ`, і розбіжність стерегла лише проба. Тепер він виводиться з неї —
    порядок той самий, тож промпт байт у байт той, що доти. Поза ним — виміри розмови
    (`ПОЛЯ_ВИМІРІВ_РОЗМОВИ`: їх `паспорт_кодами` пише окремо). Рух — один перелік `movement`
    (НП-в, рядок 280), тож окремого зведення для нього нема."""
    import паспорт_нагоди as _ПН
    свої = set(_ПН.ПОЛЯ_ВИМІРІВ_РОЗМОВИ)
    return tuple((ключ, перелік) for _, перелік, ключ in _ПН.ПОЛЕ_ВИМІРУ if ключ and ключ not in свої)


_ПАСПОРТ_ЧИСЛА = (("година", "hour"), ("темп_c", "temperature_c"), ("тривалість_год", "duration_h"),
                  ("ноги_вище_см", "legs_above_cm"))
_ГРУПИ_ВЕТО = (("типи", ("item_type", "slot", "feature", "length")), ("кольори", ("color_name", "color_class")),
               ("тканини", ("fabric",)), ("принти", ("pattern",)), ("зони", ("zone",)))


def _є(v):
    """Чи значення паспорта несе щось (не None, не порожнє, не «невідомо»)."""
    return v not in (None, "", "невідомо", U, [], {})


def паспорт_кодами(п):
    """Паспорт ядра → внутрішня мова для моделі розмови: ті самі поля сценарію кодами, без цитат.

    Типова нагода речі з фото й замовчування форми — НЕ її слова (рядок 152, В-2): модель їх не
    бачить, як і в виклику 0 (`промпт_паспорта`), інакше повернула б їх як сказане. Бажання —
    кодами (`бажання_коди`), межі — з `вето` ядра назад у коди тих самих переліків."""
    import паспорт_нагоди as _ПН
    п = п if isinstance(п, dict) else {}
    дж = п.get("джерело_полів") if isinstance(п.get("джерело_полів"), dict) else {}
    типові = set(_ПН.типові_з_форми(п))
    вих = {}
    for ключ, поле in _паспорт_прості():
        if (ключ == "нагода" and дж.get("нагода") == _ПН.ТИПОВА_НАГОДА_РЕЧІ) or ключ in типові:
            continue          # типове місце плитки — не її слово (ТИПОВЕ-1)
        к = _ВМ.код(поле, п.get(ключ)) if _є(п.get(ключ)) else None
        if к and not (поле == "intent" and к == "conventional"):     # «нічого з цього» — типове коду
            вих[поле] = к
    for ключ, поле in _ПАСПОРТ_ЧИСЛА:
        if _є(п.get(ключ)) and ключ not in типові and isinstance(п.get(ключ), (int, float)):
            вих[поле] = п[ключ]
    if _є(п.get("подія")):
        вих["event"] = str(п["подія"])
    if _є(п.get("місце_слова")) and "place" in вих:
        вих["place_words"] = str(п["місце_слова"])
    if _є(п.get("пояснення_мови")):
        вих["stylist_note"] = str(п["пояснення_мови"])
    for ключ, (поле, перелік, список) in _ПН.ПОЛЯ_ВИМІРІВ_РОЗМОВИ.items():      # НГ-4: те, що вона вже сказала
        if список and isinstance(п.get(ключ), list):
            коди = [к for к in (_ВМ.код(перелік, x) for x in п[ключ]) if к]
            if коди:
                вих[поле] = коди
        elif not список and _є(п.get(ключ)) and _ВМ.код(перелік, п[ключ]):
            вих[поле] = _ВМ.код(перелік, п[ключ])
    ош = п.get("ошатність")
    if isinstance(ош, (list, tuple)) and len(ош) == 2:
        вих["formality"] = {"from": ош[0], "to": ош[1]}
    мк = п.get("макіяж") if isinstance(п.get("макіяж"), dict) else {}
    мк_к = {к: v for к, v in (("level", _ВМ.код("makeup_level", мк.get("рівень"))),
                             ("lips_hex", мк.get("губи") if _є(мк.get("губи")) else None)) if v}
    if мк_к:
        вих["makeup"] = мк_к
    реєстри = [к for к in (_ВМ.код("register", р) for р in п.get("реєстр_людини") or []) if к]
    if реєстри:
        вих["registers"] = реєстри
    бажання = []
    for б in п.get("бажання_коди") or []:
        if isinstance(б, dict):
            р = {поле: _ВМ.код(поле, б.get(ключ)) for ключ, поле in (
                ("слот", "slot"), ("тип", "item_type"), ("колір", "color_name"), ("клас_кольору", "color_class"),
                ("тканина", "fabric"), ("візерунок", "pattern"), ("довжина", "length"), ("ознака", "feature"))
                if б.get(ключ)}
            р = {к: v for к, v in р.items() if v}
            if р and р not in бажання:
                бажання.append(р)
    if бажання:
        вих["wants"] = бажання
    межі, вето = [], п.get("вето") if isinstance(п.get("вето"), dict) else {}
    for група, поля in _ГРУПИ_ВЕТО:
        for w in вето.get(група) or []:
            к = next(((поле, _ВМ.код(поле, w)) for поле in поля if _ВМ.код(поле, w)), None)
            if к and {к[0]: к[1]} not in межі:
                межі.append({к[0]: к[1]})
    if межі:
        вих["vetoes"] = межі
    for ключ, поле in (("настрій", "mood"), ("решта", "rest")):
        сп = [_текст(x) for x in (п.get(ключ) or []) if _текст(x)]
        if сп:
            вих[поле] = сп
    речі = []
    for р in п.get("речі_з_фото") or []:
        if isinstance(р, dict) and (р.get("назва") or р.get("слот")):
            р_к = {"name": str(р.get("назва") or ""), "slot": _ВМ.код("slot", р.get("слот"))}
            if р.get("фото"):
                р_к["from_photo"] = True
            речі.append({к: v for к, v in р_к.items() if v})
    if речі:
        вих["own_items"] = речі
    return вих


def плитки_кодами(сценарій):
    """Що вона обрала плитками, кодами — без замовчувань форми (В-2: 11:00 і 18 °C вона не називала;
    ТИПОВЕ-1: і місця, яке плитка нагоди ставить сама)."""
    import паспорт_нагоди as _ПН
    с = сценарій if isinstance(сценарій, dict) else {}
    типові = set(_ПН.типові_поля_форми(с))
    вих = {}
    for ключ, поле in (("нагода", "occasion"), ("місце", "place"), ("дрес_код", "dress_code"),
                       ("прикраси", "jewelry")):
        к = _ВМ.код(поле, с.get(ключ)) if _є(с.get(ключ)) and ключ not in типові else None
        if к:
            вих[поле] = к
    for ключ, поле in (("година", "hour"), ("темп_c", "temperature_c")):
        if _є(с.get(ключ)) and ключ not in типові and isinstance(с.get(ключ), (int, float)):
            вих[поле] = с[ключ]
    if "hour" in вих and isinstance(с.get("хвилини"), int) and 0 < с["хвилини"] < 60:
        вих["minute"] = с["хвилини"]
    мк = _ПН.макіяж_канон(с.get("макіяж"))
    if isinstance(мк, dict) and _ВМ.код("makeup_level", мк.get("рівень")):
        вих["makeup"] = {"level": _ВМ.код("makeup_level", мк.get("рівень"))}
    return вих


# ── ПРОФІЛЬ КОДАМИ — БЕЗ ДРАПІРОВКИ (п.9) ─────────────────────────────────────────────
# Колорит людини — той самий, що бачить вибір палітри (`вибір_палітри._особа`, #411): контраст,
# підтон, сім'ї очей, волосся й шкіри. МЕТАЛ ДО ЛИЦЯ (відповідь драпіровки) і джерело підтону
# сюди не йдуть: драпіровку в розмові не питають і моделі розмови її не показують. Рахується
# один раз на профіль (`_ПРОФІЛЬ_ПАМ_ЯТЬ` — ключ лише з полів людини): розмова щоходу міняє
# паспорт, а профіль — ні.
_ПОЛЯ_ПРОФІЛЮ = ("шкіра", "волосся", "очі", "очі_кільце", "зріст", "обхвати", "самозвіт", "драп_сирий",
                 "схема", "гілка", "вибір_кольору")
_ПРОФІЛЬ_ПАМ_ЯТЬ = {}


def профіль_кодами(вхід):
    """Профіль із входу показу → {colouring, palette, height_cm, measured, missing} кодами й числами.
    Без кольорів у профілі колориту нема — і так і сказано в `missing`."""
    в = {к: (вхід or {}).get(к) for к in _ПОЛЯ_ПРОФІЛЮ if (вхід or {}).get(к) not in (None, "", [], {})}
    ключ_ = _json_.dumps(в, ensure_ascii=False, sort_keys=True, default=str)
    if ключ_ in _ПРОФІЛЬ_ПАМ_ЯТЬ:
        return _ПРОФІЛЬ_ПАМ_ЯТЬ[ключ_]
    вих, бракує = {}, []
    if all(в.get(к) for к in ("шкіра", "волосся", "очі")):
        import вибір_палітри as _ВП
        import дріт_моделі as _ДМ
        пер = _ВП.перелік(в)
        if not пер.get("помилка"):
            о = dict(пер.get("особа") or {})
            о.pop("metal", None)                                   # драпіровка — лише профіль (п.9)
            if isinstance(о.get("undertone"), dict):
                о["undertone"] = о["undertone"].get("class")
            for риса in ("eyes", "hair", "skin"):
                if isinstance(о.get(риса), dict):
                    о[риса] = {к: v for к, v in о[риса].items() if к in ("family", "yellow_blue")}
            if isinstance(о.get("contrast"), dict):
                о["contrast"] = о["contrast"].get("level")
            вих["colouring"] = о
            її = пер.get("її") or {}
            пал = {"scheme": _ДМ._СХЕМА.get(її.get("схема"), її.get("схема")) if її.get("схема") else "stylist_choice",
                   "saturation": _ВП._ГАМА_КОД.get(її.get("гама"), її.get("гама")) if її.get("гама") else "stylist_choice"}
            if її.get("база"):
                пал["base"] = _ВП._її_основа_дротом(її["база"])
            вих["palette"] = пал
        else:
            бракує.append("colouring")
    else:
        бракує.append("colours")
    if в.get("зріст"):
        вих["height_cm"] = в["зріст"]
    else:
        бракує.append("height")
    # обхвати кодами таблиці `girth` (рядок 1445, п.12): доти тут їхали слова «груди», «плечі»
    обхвати = sorted(_ВМ.код("girth", к) or _ВМ.UNKNOWN for к, v in (в.get("обхвати") or {}).items() if v)
    if обхвати:
        вих["measured"] = обхвати
    if бракує:
        вих["missing"] = бракує
    if len(_ПРОФІЛЬ_ПАМ_ЯТЬ) >= 8:
        _ПРОФІЛЬ_ПАМ_ЯТЬ.clear()
    _ПРОФІЛЬ_ПАМ_ЯТЬ[ключ_] = вих
    return вих


def _обовʼязкове_до(сценарій, паспорт):
    """Обовʼязкові коди на стані ДО її нового повідомлення — ті самі умови, що в шві."""
    import паспорт_нагоди as _ПН
    import сценарій as _СЦ
    п = паспорт if isinstance(паспорт, dict) else {}
    if _СЦ.є_сценарій(_СЦ.з_показу(сценарій or {}, п)[0]):
        return []
    return ["event_place"] if _ПН.подія_названа(п) else ["occasion"]


def теми_відкриті(паспорт, сценарій=None):
    """Теми поради, яких у цій розмові ще не пропонували й поле яких паспорт ще не знає, —
    кандидати для моделі (умову «на стані після ходу» перевіряє вона, а судить код)."""
    import паспорт_нагоди as _ПН
    п = паспорт if isinstance(паспорт, dict) else {}
    дані = set(п.get("поради_дані") or [])
    # поле вже знає паспорт — теми нема на жодному стані (умова кожної теми вимагає «не знає»)
    ст = _ПН._стан_для_поради(сценарій or {}, п, "")
    знає = {"goal": ст["мета"], "makeup": ст["макіяж"], "movement": ст["рух"] or ст["тривалість"],
            "temperature": ст["темп_c"] not in (None, ""), "jewelry": ст["прикраси"], "register": ст["реєстр"],
            "occasion": ст["нагода"] or ст["місце"] or ст["подія"]}
    return [к for к in _ВМ.ТЕМИ_ПОРАДИ if _ВМ.ключ("advice_topic", к) not in дані and not знає.get(к)]


def теми_за_умовою(паспорт, d):
    """Відкриті теми поради (`теми_відкриті`), поділені умовою на стані ДО її нового повідомлення:
    {advice_topics: умова вже правдива, advice_topics_if: стане правдивою лише з її нових слів}.

    Рядок 1441 (розбір 02.10): з одним переліком модель сама звіряла умову кожної теми й 9 разів
    запросила до теми, умова якої не виконана (температура й рух для театру, клубу, офісу; мета й
    макіяж для пляжу вдень), — здебільшого на пізніх ходах, де сцена вже стоїть у паспорті. Умову
    на цьому стані код рахує сам тим самим суддею (`паспорт_нагоди.теми_дозволені`), що й після
    ходу; суд частин (`суд_частин`) лишається на стані ПІСЛЯ ходу."""
    import паспорт_нагоди as _ПН
    п = паспорт if isinstance(паспорт, dict) else {}
    відкриті = теми_відкриті(п, d.get("сценарій"))
    є_річ = bool(d.get("фото") or п.get("речі_з_фото"))
    драп = dict(п.get("драп_сирий") or {}, **(d.get("драп_сирий") or {})) or None
    зараз = {_ВМ.код("advice_topic", т) for т in _ПН.теми_дозволені(
        d.get("сценарій") or {}, п, драп=драп, є_річ=є_річ, контраст=контраст_профілю(d.get("профіль")))}
    return {"advice_topics": [т for т in відкриті if т in зараз],
            "advice_topics_if": [т for т in відкриті if т not in зараз]}


def контраст_профілю(профіль):
    """Рівень контрасту обличчя з кольорів профілю («низький» | «середній» | «високий») або None — той
    самий вимір, що `особа.рівень` пакета (`міст_вхід._features` → `outfit.контраст_особи`, як у
    `міст_основи`); зросту й мірок не треба. МАК-2: ним суддя тем знає, чи доречна тема «макіяж»
    удень (`паспорт_нагоди.порада_коду`). Без шкіри, волосся й очей — None, тема як доти."""
    if not isinstance(профіль, dict) or not all(профіль.get(к) for к in ("шкіра", "волосся", "очі")):
        return None
    import міст_вхід as _МВ
    import outfit as _O
    о = _O.контраст_особи(_МВ._features(профіль)[0])
    return о.get("рівень") if о.get("доступно") else None


# Причини відповіді ходу, на які показ робить ОДИН повтор (рядок 3170) — коди `прийняти_розмову.причина`
# до двокрапки; у промпт їде сам код, опис — у рядку поля `format_error` оголошення.
ПРИЧИНИ_ПОВТОРУ = ("not_json_object", "no_text_field", "unknown_key")

# КЛЮЧ ПОЗА СХЕМОЮ — ОДИН ПОВТОР З ЙОГО НАЗВОЮ (рядок 6523, ЖИВІ-1016-1 Ж:20 сід 5). `preciptation: {quote: «сніг», value:
# snow}` — описка справжнього поля: шов брав лише рядок `not_read`, і сніг до паспорта не доходив. Словника описок нема
# (п.12): код бачить, що ключ `update` не є полем сценарію, і просить ту саму форму ходу ще раз, називаючи ключ.
# Це НЕ причина відмови: хід прочитано (`причина` порожня), тож другу спробу, що вийшла гірше (нечитана), показ відкидає
# й лишає першу. Ключі, якими модель повторила ВХІД промпта (`photos`, `required`, `advice_topics`), частини ходу (`need`, `text`) і
# форму пари (`quote`), — не поля, а луна: повтор їх не лікує, лише коштує виклику.
_НАЗВА_КЛЮЧА = re.compile(r"[a-z][a-z_]{0,39}")


def _ключі_поза_схемою(незнайомі, оновлення):
    """Не більше трьох ключів `update`, що не є полем сценарію й не луна входу ходу, — назвами для повтору."""
    луна = {п.шлях for п in РОЗМОВА.вхід} | set(_ЧАСТИНИ) | {"quote"} | set(_ЗНАЧЕННЯ_ПАРИ)
    поля = ВИДИ_ВХОДУ["scenario"]["поля"]
    return [x for x in dict.fromkeys(незнайомі) if isinstance(x, str) and x in оновлення and x not in поля
            and x not in луна and _НАЗВА_КЛЮЧА.fullmatch(x)][:3]


def хід_плиток(d):
    """Чи це хід плиток: вхід ендпойнта з розмовою, де її нового листа нема (рядок 6185)."""
    р = d.get("розмова") if isinstance(d.get("розмова"), dict) else {}
    return not str(р.get("нове") or "").strip()


def промпт_розмови(d):
    """Промпт ходу розмови зі входу ендпойнта: {розмова: {нове, історія}, сценарій, паспорт?,
    драп_сирий?, фото?, профіль?, помилка_формату?} → текст промпта (JSON шаблону збирача, стала частина спершу).
    Без її листа — хід плиток (`ХІД_ПЛИТОК`): плитки, паспорт, профіль і вада формату."""
    import паспорт_нагоди as _ПН
    р = d.get("розмова") if isinstance(d.get("розмова"), dict) else {}
    паспорт = d.get("паспорт") if isinstance(d.get("паспорт"), dict) else {}
    причина = str(d.get("помилка_формату") or "")
    вада = next((к for к in ПРИЧИНИ_ПОВТОРУ if причина.split(":")[0] == к), None)
    if вада == "unknown_key":      # назви ключів — частина форми повтору (`_ключі_поза_схемою` пускає лише [a-z_])
        вада = "unknown_key: " + ", ".join(x for x in re.split(r"[:,\s]+", причина)[1:] if _НАЗВА_КЛЮЧА.fullmatch(x))
    if хід_плиток(d):     # рядок 6185: без її листа — своє коротке оголошення
        return _json_.dumps(_ЗП_Р.зібрати(ХІД_ПЛИТОК, {"profile": профіль_кодами(d.get("профіль") or {}),
                                                     "passport": паспорт_кодами(паспорт),
                                                     "chosen": плитки_кодами(d.get("сценарій")),
                                                     "format_error": вада}), ensure_ascii=False)
    репліки, раніше = _ПН.вікно_розмови(р.get("історія") or [], остання_ціла=False)
    обовʼязкове = _обовʼязкове_до(d.get("сценарій"), паспорт)
    раніше = {"turns": раніше["ходів"], "her_messages": раніше["її_слова"]} if раніше else None
    дані = {"profile": профіль_кодами(d.get("профіль") or {}),
            "earlier_conversation": раніше, "conversation": репліки,
            "passport": паспорт_кодами(паспорт), "chosen": плитки_кодами(d.get("сценарій")),
            # Рядок 3930 (ЖИВІ-15 №1–9): тема поради `occasion` стояла в `advice_topics_if` поруч із
            # `required: [occasion]` — те саме питання двома каналами, і модель ставила його в `invite`. Код
            # обовʼязкового питання темою поради не йде: його питає `ask`.
            **{к: [т for т in в if т not in обовʼязкове] for к, в in теми_за_умовою(паспорт, d).items()},
            "required": обовʼязкове,
            "photos": [str(ф.get("ід")) for ф in (d.get("фото") or []) if isinstance(ф, dict) and ф.get("ід")],
            "format_error": вада,
            "her_new_message": str(р.get("нове") or "").strip() or U}
    return _json_.dumps(_ЗП_Р.зібрати(РОЗМОВА, дані, мова_тексту="Ukrainian"), ensure_ascii=False)


# ── ВІДПОВІДЬ ХОДУ: ОНОВЛЕННЯ — ТІЄЮ САМОЮ МОВОЮ СЦЕНАРІЮ, ЧАСТИНИ — ОКРЕМО ─────────────
_ЧАСТИНИ = ("need", "text", "invite_topics", "invite", "ask_code", "ask", "header")
ШАПКА_СИМВ = 60      # стеля символів на слова одного поля: шматок шапки — плашка в один рядок на 390 px
_КОД_У_ТЕКСТІ = re.compile(r"\b[a-z]+_[a-z_]+\b|\bunknown\b")


# ШАПКА — ЛИШЕ ПРО ПОЛЕ, ЯКЕ ХІД ЗАПИСАВ КОДОМ (рядок 6454, ЖИВІ-1016-1, п.12).
# ЩО БУЛО. `header` першого ходу MamayLM заповнює на всіх шести ключах, хоч поля не знає: «немає» (Ж:34), «Відсутній»,
# «Без обмежень» (Ж:42), «час не названо» (Ж:19), «температура невідома», «опадів немає» (Ж:32), «вісімнадцята» з її
# «увечері» (Ж:45), «open» (Ж:20), «celebration» на бажаннях (Ж:23). `_шапка` судила лише слова (порожнє, задовге, код
# латинкою) і пропускала 7 шапок з 16; словник «немає/відсутній» у `_ВМ.невідомо` — це читати слова.
# ЩО СТАЛО. Шапка — слова до значення поля, тож її ключ іде лише тоді, коли поле цього ходу записано кодом
# (`внутрішня` після розбору `update`; поле, яке код не взяв, там відсутнє): інакше `not_in_update`, слів код не
# читає. Давні слова поля паспорт тримає сам, доки значення те саме (`паспорт_нагоди.шапка_чинна`). Ключ скелета
# цілим («hour | temperature_c | …» — Ж:24) — вада форми `skeleton_key`, не незнайомий ключ; хід через неї не
# повторюється: `update` Ж:24 прочитано повністю, а повтор — ще 19 с і ризик іншого `update`. Цифра впритул до літери
# («+18к», Ж:45) — форма зіпсованого письма (`glued_digit`), як код латинкою.
_ЦИФРА_ВПРИТУЛ = re.compile(r"\d[^\W\d_]")


def _шапка(об, незнайомі, внутрішня):
    """`header` відповіді ходу → {поле паспорта: слова}; ключ поза `паспорт_нагоди.ШАПКА_ПОЛЯ`, ключ скелета цілим, поле,
    якого `внутрішня` цього ходу не записала, порожнє, задовге чи з кодом (форма письма, слів код не читає) — у
    `незнайомі` рядком `header.<ключ>=<чому>`."""
    import паспорт_нагоди as _ПН
    вих, в = {}, внутрішня if isinstance(внутрішня, dict) else {}
    for к, т in (об.items() if isinstance(об, dict) else ()):
        поле = dict(_ПН.ШАПКА_ПОЛЯ).get(_код(к))
        т = " ".join(т.split()) if isinstance(т, str) else ""
        чому = ("skeleton_key" if к in СКЕЛЕТ_РОЗМОВИ["header"] else "unknown_key" if not поле else
                "empty" if _порожнє(т) or _ВМ.невідомо(т) else
                "not_in_update" if _порожнє(в.get(_код(к))) or _ВМ.невідомо(в.get(_код(к))) else
                "too_long" if len(т) > ШАПКА_СИМВ else
                "code_in_text" if _КОД_У_ТЕКСТІ.search(т) else "glued_digit" if _ЦИФРА_ВПРИТУЛ.search(т) else None)
        if чому:
            незнайомі.append("header.%s=%s" % (к, чому))
        else:
            вих[поле] = т
    return вих


# ── КОД МЕТИ Й НАМІРУ — НА СВОЄМУ ПОЛІ (рядок 2380) ──────────────────────────────────────
# ЩО БУЛО. Живий пачки 3+4, Н1 (MamayLM, «головне щоб без претензій, вона завжди до чогось чіпляється»): модель
# розмови ДВІЧІ з двох (ДО і ПІСЛЯ) поклала `context_optimal` у `goal`, а в `intent` — інший код на тому самому
# уривку: ДО `conventional`, ПІСЛЯ `statement` (її ж `text`: «не привернути зайвої уваги»). `goal` такого коду не
# знає — він ішов у `незнайомі`, а `intent` приймався як є: намір statement, доза «на межі» 0 → 273 і картка
# «сміливий вибір» жінці, що боїться зауважень. Так само хід плиток Н1 (seed3_06) і Н3 (seed3_10).
# ЩО СТАЛО. Переліки мети й наміру не перетинаються, тож код одного з них на полі іншого — значення ТОГО поля,
# чий це код: шов ставить пару {quote, value} туди, де цей код живе (слів не читає — лише коди переліків, п.12).
# Значення, що стояло на тому полі, тоді поступається: того самого уривка не можуть нести два наміри, а
# вибраний з чужого переліку код модель брала навмисно — у записаних ходах саме він збігався з її `text`.
# Обидва коди не на своїх полях — міняються місцями. Що перенесено — у `перенесено` (`goal->intent`).
# ПОГОДА Й ОПАДИ — ТАК САМО, АЛЕ БЕЗ ПЕРЕБИВАННЯ (рядок 2811). Живий пачки 5: «обіцяють можливо дощ» MamayLM
# поклала `weather_feel: possible_rain` (Д2), «увесь день дощ» — `weather_feel: rain` (Д3); код не з переліку
# відчуттів ішов у `незнайомі`, і паспорт казав `опади: невідомо` — дощ губився мовчки. Переліки відчуття й
# опадів теж не перетинаються, тож код опадів на полі відчуття — опади з тією самою цитатою (і навпаки). На
# відміну від мети й наміру, відчуття й опади — два різні факти дня: власний код сусіднього поля лишається, а
# чужий тоді — у `незнайомі`, як доти.
# ЇЇ МЕЖА ВІДКРИТОГО НА ЗОНАХ МЕТИ (рядок 3741, ЖИВІ-14 №1, №2, №11). «Відкритого не хочу» MamayLM у 3 з 3 сідів
# писала `goal_zones: {quote, value: "none"}` (ЖИВІ-13 — `open_zones` 3 з 3): «none» — не зона тіла, код брав його
# як невідомо (`unknown_value · field=goal_zones`), і пряма межа губилась. «none» — код `open_zones`, а переліки
# зон мети й кількості відкритих зон не перетинаються: шов ставить пару на `open_zones`, як погоду на опади; власний
# код `open_zones` лишається сильнішим. Перелік зон мети — `goal_zone`: таблиця поля `goal_zones` не має, тож
# «свого» коду там шов не бачить і переносить лише код, який знає `open_zones`.
# КОД МІСЦЯ НА МІСЦІ СЛОВАМИ (рядок 3662). У перших ходах ЖИВІ-12/13/14 модель 6 разів поклала в `place_words` сам код
# місця — `{quote: "на роботу", value: "office"}`, `cafe` на «кава з подругою», `Park` на «парк» — без `place`; слова
# живуть лише при місці, і місце губилось разом із ними. `place_words` переліку не має, тож значення, яке знає
# перелік `place`, — це місце з тим самим уривком (сторож його звіряє); власний код `place` лишається сильнішим.
# КОД МІСЦЯ НА НАГОДІ, МЕТА Й «ЩО ЩЕ ВАЖЛИВО» (рядок 6457, ЖИВІ-1016-1). Перший хід «Йду ввечері в клуб» — `occasion:
# {quote, value: "club"}` (Ж:34), «…в бар з друзями» — `"bar"` (Ж:39): `club` і `bar` — коди `place`, нагода такого
# коду не знає, поле йшло в `незнайомі`, і перепитування «куди ти збираєшся ввечері?» йшло жінці, що щойно сказала
# куди. Так само `goal: ["taller"]` (Ж:27; `taller` — код `goal_extra`) і `goal_extra: ["conceal"]` (Ж:44; код `goal`).
# Спільні коди нагоди й місця (walk, theatre, home…) лишаються на своєму полі: шов переносить лише код, якого поле
# не знає; власний код сусіда сильніший.
# НАМІР З КОДОМ «ДОВШОЇ ЛІНІЇ» (рядок 6086, ЖИВІ-14 17/seed1_02). Пара `goal → goal_extra` є (`goal: taller`), а `intent:
# {quote: «хочу виглядати вищою», value: taller}` — ні: `taller` — код `goal_extra`, намір його не знає, і «вище» губилось
# разом з полем. Той самий шов, що для `goal`: код, якого поле не знає, а `goal_extra` знає, стає значенням `goal_extra`
# з тим самим уривком; власний код `goal_extra` сильніший (як у `goal`).
# КОД МІСЦЯ НА НАГОДІ (рядок 6600, ЖИВІ-1016-2 ж5_похорон, сіди 3–5). «Похорон дідуся в четвер зранку» MamayLM у 3 з 3
# сідів писала `occasion: funeral` — це код переліку `place` (Похорон), не нагоди: нагода йшла в `незнайомі`, місце
# лишалось словами, паспорт без жодного визначального поля, і «Зібрати образи» відкривала аркуш нагоди без плитки
# «Траур» — збирання не стартувало (проба `проби/зависання_ж5_нагода.py`). Спільні коди обох переліків (theatre,
# sport…) лишаються нагодою; власний код `place` — сильніший.
_СУСІДИ_КОДІВ = (("goal", "intent", True), ("intent", "goal", True),
                 ("weather_feel", "precipitation", False), ("precipitation", "weather_feel", False),
                 ("goal_zones", "open_zones", False), ("place_words", "place", False),
                 ("occasion", "place", False), ("goal", "goal_extra", False), ("goal_extra", "goal", False),
                 ("intent", "goal_extra", False))


# ЇЇ РІЧ НА КЛЮЧІ СВОГО СЛОТА (рядок 3310, живі 12 Б/01–03). «Одягну своє взуття з фото» MamayLM у 3 з 3 сідів
# писала в `update` поле `shoes{quote, status: has, …}` — такого поля сценарію нема, і її річ ішла в `незнайомі`.
# Стан `status` (has | maybe | not_wanted) — код лише її речі (`внутрішня_мова.ЇЇ_РІЧ`), а ключ — код слота: шов
# кладе такий запис в `own_items` зі слотом ключа (слів не читає — лише коди переліків, п.12); у `перенесено` —
# `shoes->own_items`. Тип і колір, які модель дописала речі з фото, коду не потрібні: її річ з фото міряє шар фото.
# ФОРМА ЇЇ РЕЧІ — ДРІБНІ ВІДХИЛЕННЯ ПРОЩАЄ СТОРОЖ ШАРУ (ВЛАСНІ-РЕЧІ-34, рядок 4420; ЖИВІ-19 №8, ЖИВІ-22 №02–04).
# «Одягну своє взуття з фото» MamayLM у 5 з 5 записаних ходів дала її річ кривою формою: `own_items: [{name: {quote,
# status: has}}]` (Ж19 №8, Ж22 №02 — стан і уривок усередині назви) і `shoes: {quote, value: {name, status:
# own_items}}` (Ж22 №03–04 — пара на ключі слота, а стан — кодом самого поля). Річ не записувалась: у першому разі
# `own_item_without_status` → `not_recorded: own_items`, і репліка казала разом «твої сандалі пасують» (вердикт речі з
# фото) і «я не записала твої речі»; у другому `shoes` мовчки йшло в `незнайомі`. Шов розгортає форму, не слова
# (п.12): пара {quote, value: {…}} — запис зі значення й уривком; `status`/`quote` усередині `name` — на рівень речі
# (назва — уривок, коли іншого в ній нема); стан кодом поля `own_items` — `has`: модель назвала річ її річчю, а
# стану «не певна» чи «не хоче» не дала. Кроки — у `перенесено` (`own_items.form`).
def _її_річ_формою(x):
    """(запис її речі з розгорнутою формою, чи щось розгорнуто)."""
    if not isinstance(x, dict):
        return x, False
    було = x
    з = x.get("value")
    if isinstance(з, dict) and not {"name", "status", "slot", "item_type"} & set(x):
        x = dict({к: v for к, v in x.items() if к != "value"}, **{к: v for к, v in з.items() if к not in x})
    н = x.get("name")
    if isinstance(н, dict) and "status" in н and "status" not in x:
        лишок = {к: v for к, v in н.items() if к not in ("status", "quote")}
        x = dict(x, status=н["status"], **({"quote": н["quote"]} if н.get("quote") and not x.get("quote") else {}))
        x["name"] = лишок or x.get("quote")
    if _код(_пара("status", {}, x.get("status"))[0]) == "own_items":
        x = dict(x, status="has")
    return x, x is not було


def _її_речі_формою(оновлення):
    """(оновлення, де кожен запис `own_items` розгорнуто `_її_річ_формою`, перенесене кодами)."""
    сп = оновлення.get("own_items")
    сп = [сп] if isinstance(сп, dict) else сп
    if not isinstance(сп, list):
        return оновлення, []
    пари = [_її_річ_формою(x) for x in сп]
    if not any(з for _, з in пари):
        return оновлення, []
    return dict(оновлення, own_items=[x for x, _ in пари]), ["own_items.form"]


def _її_річ_на_слоті(оновлення):
    """(оновлення, де запис зі станом її речі на ключі-коді слота стоїть в `own_items`, перенесене кодами)."""
    статуси = [к for к in _ВМ.ЇЇ_РІЧ["status"]["enum"] if к != U]
    речі, перенесено = [], []
    for к, v in оновлення.items():
        сп = [_її_річ_формою(x)[0] for x in (v if isinstance(v, list) else [v])]
        if к in _ВМ.СЦЕНАРІЙ or not _ВМ.ключ("slot", _код(к)) or not сп \
                or not all(isinstance(x, dict) and _код(x.get("status")) in статуси for x in сп):
            continue
        речі += [dict(x, slot=x.get("slot") or _код(к)) for x in сп]
        перенесено.append("%s->own_items" % к)
    if not речі:
        return оновлення, []
    нове = {к: v for к, v in оновлення.items() if "%s->own_items" % к not in перенесено}
    було = нове.get("own_items")
    нове["own_items"] = (було if isinstance(було, list) else [було] if isinstance(було, dict) else []) + речі
    return нове, перенесено


# ГОДИНА, ЯКУ МОДЕЛЬ САМА НАЗВАЛА ПОРОЮ ДНЯ (рядок 3661, ЖИВІ-14 №5–7). «Субота ввечері» MamayLM у 3 з 3 сідів писала
# `hour: {quote: "субота ввечері", value: 19 | 18}` і в тому ж `update` — `part_of_day: evening`, хоч промпт тричі
# каже, що пора без годинника — `part_of_day`, не година; година брала гору, і паспорт стояв на вигаданих 19:00.
# `part_of_day` промпт дає «лише коли години нема» — обидва поля в одному ході означають, що модель сама прочитала
# її слова порою дня. Шов лишає пору, а година й хвилини не беруться (слів не читає — лише які поля стоять, п.12);
# у `перенесено` — `hour->part_of_day`. Справжня година (о 16:00 — ЖИВІ-12/13/14) у записаних ходах пори поруч не
# має ні разу; коли матиме, пора дня — м'якше, але правдиве, а вигадана година — ні.
# ГОДИНА БЕЗ ЦИФРИ В УРИВКУ (рядок 4204, ЖИВІ-18 №7–8): та сама вигадана година вже й без пори поруч —
# `hour {quote: «субота ввечері», value: 19}`, `{quote: «ввечері», value: 18}` (Ж13–Ж18 — 12 ходів), а також
# `{quote: «надворі мороз», value: 23}` (Ж16 №11) і `{quote: "", value: 9}` на «йога зранку» (Ж17 №13). Справжня
# година в записаних ходах ЖИВІ-12…18 — щоразу з цифрою («о 16:00»). Тож година, чий уривок цифри не має, — пора дня,
# яку модель записала годиною: шов ставить `part_of_day` тієї години (`сценарій._частина_доби`), година й хвилини не
# беруться. Код дивиться лише, чи є в уривку цифра — число, не слово (п.12). Ціна: година словами («о сьомій
# вечора») стає порою «вечір» — м'якше, але правдиве.
# ГОДИНА БЕЗ УРИВКА — ПОРА З ЧИСЛА (рядок 3800, ЖИВІ-13 А/06 `seed3_01`): `hour: 19` голим числом, без пари й без `part_of_day`.
# Сторож `_тримається` знімає годину без уривка, і «субота ввечері» зникала цілком — ні години, ні пори. Тепер пора — з
# числа тією самою `_частина_доби`: година без її уривка не стає годиною (сторож лишається), а частина доби, названа
# числом, не губиться.
def _година_при_порі(оновлення):
    """(оновлення без `hour` і `minute`, коли той самий хід дав і `part_of_day`, або уривка години нема, або він не має
    цифри — тоді з `part_of_day` цієї години; перенесене кодами)."""
    година, уривок = _пара("hour", {}, оновлення.get("hour"))
    if "hour" not in оновлення or _порожнє(година):
        return оновлення, []
    без_години = {к: в for к, в in оновлення.items() if к not in ("hour", "minute")}
    if _ВМ.ключ("part_of_day", _код(_пара("part_of_day", {}, оновлення.get("part_of_day"))[0])):
        return без_години, ["hour->part_of_day"]
    цит = оновлення.get("quotes")
    уривок = уривок if уривок is not None else цит.get("hour") if isinstance(цит, dict) else None
    try:
        г = int(float(година))
    except (TypeError, ValueError):
        return оновлення, []
    if (уривок is not None and re.search(r"\d", str(уривок))) or not 0 <= г <= 23:
        return оновлення, []
    import сценарій as _СЦ
    return dict(без_години, part_of_day=_СЦ._частина_доби(г)), ["hour->part_of_day"]


# СПИСОК НА ПОЛІ ОДНОГО ЗНАЧЕННЯ — ПЕРШЕ ЗНАЧЕННЯ (рядок 6457, ЖИВІ-1016-1). «Пробіжка зранку, потім обід з колегою» —
# `occasion: {quote, value: ["sport", "work"]}` і `part_of_day: ["morning", "day"]` (Ж:36), «йога зранку, потім кава» —
# `occasion: ["work", "celebration"]`, `place: ["cafe", "bar"]` (Ж:49): поле одного значення списку не бере, і вся
# нагода йшла в `незнайомі` мовчки — жінка чула «На яку подію?». Код слів не читає (п.12): бере перше значення
# (модель пише частини дня по черзі, перша — та, що названа першою), пара лишається зі своїм уривком; решта — рядком
# `не_взято` (`list_rest`), а в `перенесено` — `<поле>.list_pick`.
# ВІЛЬНЕ ПОЛЕ СПИСКОМ — ТАК САМО (рядок 6087, ЖИВІ-14 06/seed3_01): `event: {quote: «урок вокалу, надворі +18…», value:
# ["music school", "vocal lesson"]}` — переказ латиницею списком; шов склеював його в подію «music school, vocal lesson».
# Перше значення списку — тим самим правилом, решта — `list_rest`; рядок першого значення судить `_не_її_значення`, і
# подія лягає її уривком.
# НАГОДА СПИСКОМ — ЗА `occasion_part` ТІЄЇ САМОЇ ВІДПОВІДІ (рядок 6522, доповнення менеджера). Частину дня, для якої
# образ, обирає модель кодом `occasion_part`; перше значення списку могло бути спортом всупереч їй («пробіжка зранку,
# потім обід» → sport). Правило — те саме, що в описі `occasion_part` («when she has not said, the first part that is
# not sport, or the sport part when there is no other»); код звіряє коди, не слова (п.12): `occasion_part` sport —
# `sport`; інакше (other, unknown чи поля нема) — перше значення, що не `sport`, а коли всі sport — `sport`.
def _значення_зі_списку(к, з, оновлення):
    """Значення поля `к` зі списку `з`: для `occasion` — за `occasion_part` того самого `update`, інакше перше."""
    if к != "occasion":
        return з[0]
    спорт = [x for x in з if _код(x) == "sport"]
    if _код(_пара("occasion_part", {}, оновлення.get("occasion_part"))[0]) == "sport" and спорт:
        return спорт[0]
    return next((x for x in з if _код(x) != "sport"), з[0])


def _перше_зі_списку(оновлення, поля):
    """(оновлення, де поле одного значення зі списком кодів чи чисел має одне значення (`_значення_зі_списку`),
    перенесене кодами, рядки `не_взято` про решту)."""
    нове, перенесено, рядки = dict(оновлення), [], []
    for к, v in оновлення.items():
        с = поля.get(к) if к != "quotes" else None
        if not isinstance(с, dict) or с.get("type") == "array" or _ref(с) in _ОБʼЄКТИ:
            continue
        з, _ = _пара(к, с, v)
        if not (isinstance(з, list) and len(з) > 1
                and all(isinstance(x, (str, int, float)) and not isinstance(x, bool) for x in з)):
            continue
        і = з.index(_значення_зі_списку(к, з, оновлення))
        if isinstance(v, list) and len(v) == len(з):  # список пар — обрана пара зі своїм уривком
            нове[к] = v[і]
        elif isinstance(v, dict):
            ключ = next(x for x in _ЗНАЧЕННЯ_ПАРИ + (к,) if x in v)
            нове[к] = dict(v, **{ключ: з[і]})
        else:
            нове[к] = з[і]
        перенесено.append("%s.list_pick" % к)
        рядки.append("list_rest · step=layer · field=%s · model_said=%s · code=not_taken"
                     % (к, _json_.dumps(з[:і] + з[і + 1:], ensure_ascii=False)))
    return нове, перенесено, рядки


# ЧИСЛО ОШАТНОСТІ — СМУГА [N, N] (рядок 6290, хід плиток живих пачки 15). У 3 з 6 ходів плиток ж1, де модель дала
# formality, вона написала її парою з одним числом — `{"quote": "Оціни мій образ", "value": 4}`: смуги {from, to} нема,
# і `formality=4` ішло в `незнайомі`, паспорт лишався без ошатності. Вибір — смуга [N, N], не повтор із `format_error`:
# число — розуміння моделі (п.14), і ширину код не вигадує (вужча смуга — те, що модель сказала, а «типова ширина» була б
# здогадом коду); повтор коштував би ще одного виклику на кожен хід плиток, а відповідь уже читається; причину повтору
# читає показ (`ПРИЧИНИ_ПОВТОРУ`), а не цей шов. Пара з двох чисел — [менше, більше]. Уривок ошатності не потрібен
# (`_БЕЗ_ЦИТАТИ`). У `перенесено` — `formality.number_band`.
def _смуга_числом(оновлення):
    """(оновлення, де formality одним числом 1–10 чи двома числами стала смугою {from, to}, перенесене кодами)."""
    if "formality" not in оновлення:
        return оновлення, []
    з, _ = _пара("formality", {}, оновлення["formality"])
    числа = з if isinstance(з, list) and 1 <= len(з) <= 2 else [з]
    if not all(isinstance(x, (int, float)) and not isinstance(x, bool) and x == int(x) and 1 <= x <= 10
               for x in числа):
        return оновлення, []
    return dict(оновлення, formality={"from": int(min(числа)), "to": int(max(числа))}), ["formality.number_band"]


def _на_своє_поле(оновлення):
    """(оновлення сценарію з кодом мети чи наміру, відчуття погоди чи опадів, нагоди чи місця, її річ на ключі слота,
    година, яку модель сама назвала порою дня, — на своєму полі, її річ — розгорнутою формою, ошатність одним числом —
    смугою, перенесене кодами). Кличе `прийняти_вхід("scenario")` — і для перекладача сценарію, і для `update` ходу
    розмови."""
    оновлення, пора = _година_при_порі(оновлення)
    оновлення, форма = _її_речі_формою(оновлення)
    оновлення, речі = _її_річ_на_слоті(оновлення)
    оновлення, смуга = _смуга_числом(оновлення)
    речі = пора + форма + речі + смуга
    чужі, перебиває = {}, {}
    for поле, сусід, сильніший in _СУСІДИ_КОДІВ:
        if поле in оновлення:
            знач, _ = _пара(поле, {}, оновлення[поле])
            if isinstance(знач, str) and not _ВМ.ключ(поле, _код(знач)) and _ВМ.ключ(сусід, _код(знач)):
                чужі[поле], перебиває[поле] = сусід, сильніший
    # сусід зі своїм кодом, що лишається на місці, — сильніший за чужий код, коли пара не перебиває;
    # сусід без власного коду (ключа нема, «unknown», порожнє) місце віддає
    чужі = {поле: сусід for поле, сусід in чужі.items()
            if перебиває[поле] or сусід in чужі
            or сусід not in оновлення or _порожнє(_пара(сусід, {}, оновлення[сусід])[0])}
    if not чужі:
        return оновлення, речі
    куди = set(чужі.values())
    нове = {к: в for к, в in оновлення.items() if к not in чужі}
    for поле, сусід in чужі.items():
        нове[сусід] = оновлення[поле]
    цит = оновлення.get("quotes")
    if isinstance(цит, dict):           # верхній `quotes`: уривок іде за полем, а не лишається під старим ключем
        нова_цит = {к: в for к, в in цит.items() if к not in чужі and к not in куди}
        нова_цит.update({сусід: цит[поле] for поле, сусід in чужі.items() if поле in цит})
        нове["quotes"] = нова_цит
    return нове, речі + ["%s->%s" % кс for кс in чужі.items()]


# ── НЕЗАКРИТИЙ ОБ'ЄКТ ХОДУ (рядок 2383) ───────────────────────────────────────────────────
# Н4 6б, хід після фото (seed3_48): модель вклала частини ходу в `update` (форма рядка 2420) і забула закрити
# зовнішній об'єкт — «Expecting ',' delimiter», хід ішов шляхом main замість оцінки. Бракує лише закривних
# дужок у кінці: шов дописує їх (до двох) і читає — форма, не слова; у `перенесено` — `unclosed_object_read`.
НЕЗАКРИТИЙ_ОБʼЄКТ = "unclosed_object_read"


def _незакритий(відповідь):
    """JSON-об'єкт відповіді, якому бракує до двох закривних «}» у кінці, або None."""
    т = re.sub(r"^```(?:json)?\s*|\s*```$", "", str(відповідь or "").strip())
    for н in (1, 2):
        try:
            об = _json_.loads(т + "}" * н)
        except ValueError:
            continue
        return об if isinstance(об, dict) else None
    return None


# ЛАПКИ З РИСКОЮ Й ПАРИ В КВАДРАТНИХ ДУЖКАХ (рядок 6068, ОЦІНКА-ЖИВИЙ-14). 4 ходи з 58 не розбирались: сцена 06 —
# усі лапки `update` з рискою (`"hour": {\"quote\": \"увечері\", …}`), сцена 22 — пара в квадратних дужках
# (`"goal_zones": [["quote": "приховати живіт", "value": ["belly"]]]`), обидві спроби. Хід ішов шляхом паспорта: 06 —
# «Театр, концерт», 22 — живіт лише бажанням, репліка паспорта питала стиль. Код читає ФОРМУ (п.12): коли відповідь
# не розбирається, «\"» поза рядком стає лапкою, а «[», за якою одразу йде ключ із двокрапкою, — «{» (і її «]» —
# «}»). Прочитане так — у `перенесено`: `escaped_quotes_read`, `bracket_pairs_read`.
ЛАПКИ_З_РИСКОЮ, ПАРИ_В_ДУЖКАХ = "escaped_quotes_read", "bracket_pairs_read"
_КЛЮЧ_ПІСЛЯ_ДУЖКИ = re.compile(r'\s*"(?:[^"\\]|\\.)*"\s*:')


def _пари_в_обʼєкти(т):
    """Текст, де «[», за якою одразу йде ключ із двокрапкою, стала «{», а її пара «]» — «}» (поза рядками)."""
    вих, стос, у_рядку, риска = list(т), [], False, False
    for і, ч in enumerate(т):
        if у_рядку:
            у_рядку, риска = (ч != '"' or риска), (ч == "\\" and not риска)
        elif ч == '"':
            у_рядку = True
        elif ч == "[":
            обʼєкт = bool(_КЛЮЧ_ПІСЛЯ_ДУЖКИ.match(т, і + 1))
            стос.append(обʼєкт)
            if обʼєкт:
                вих[і] = "{"
        elif ч == "]" and стос and стос.pop():
            вих[і] = "}"
    return "".join(вих)


def _лагоджена_форма(відповідь):
    """(JSON-об'єкт відповіді, прочитаний після лагодження форми вище, коди лагодження) або (None, [])."""
    т = re.sub(r"^```(?:json)?\s*|\s*```$", "", str(відповідь or "").replace(_ВСТАВКА, " ").strip())
    без_риски = т.replace('\\"', '"')
    for варіант, коди in ((без_риски, [ЛАПКИ_З_РИСКОЮ]), (_пари_в_обʼєкти(т), [ПАРИ_В_ДУЖКАХ]),
                          (_пари_в_обʼєкти(без_риски), [ЛАПКИ_З_РИСКОЮ, ПАРИ_В_ДУЖКАХ])):
        if варіант == т:
            continue
        try:
            об = _json_.loads(варіант)
        except ValueError:
            continue
        if isinstance(об, dict):
            return об, коди
    return None, []


# «ОЦІНИ МІЙ ОБРАЗ» — НЕ БАЖАННЯ (рядок 5980, живий 15, qwen3.5-9b мовним шаром). На 6б «Оціни мій образ — як тобі?» з
# двома фото модель дала `need: look` і `wants: [{quote: «мій образ» / уся репліка, item_type: dress_generic(, slot: set)}]`
# у 10 з 10; поле в `update`, і показ (`лишеПитанняП`) вів хід у сценарій, а не в оцінку. Слів код не читає (п.12): при
# `need: look` (вона просить судити свої речі чи образ) запис `wants` без жодної ознаки, крім уривка, слота `set` і
# загального виду (`<рід>_generic`), нічого не просить — як запис лише зі слотом (`_слот_без_ознаки`). Бажання з ознакою
# чи точним видом лишається. У `перенесено` — `wants.look_request`.
def _бажання_оцінки(в, need):
    """(внутрішня без `wants`, що при `need: look` називають лише загальну річ, перенесене кодами)."""
    сп = в.get("wants")
    if need != "look" or not isinstance(сп, list):
        return в, []
    def загальне(x):
        if not isinstance(x, dict):
            return False
        поля = {к for к, v in x.items() if not _порожнє(v)} - {"quote"}
        вид, слот = _код(x.get("item_type")), _код(x.get("slot"))
        return поля <= {"slot", "item_type"} and (not вид or str(вид).endswith("_generic")) and слот in (None, "set")
    решта = [x for x in сп if not загальне(x)]
    if len(решта) == len(сп):
        return в, []
    вих = {к: v for к, v in в.items() if к != "wants"}
    return (dict(вих, wants=решта) if решта else вих), ["wants.look_request"]


def прийняти_розмову(відповідь):
    """Відповідь моделі розмови → dict(внутрішня, частини, незнайомі, невідомо, не_взято, заглушки, причина,
    перенесено). `не_взято` — рядки звіту (`невзяте_рядком`) на кожне поле з `невідомо`: шов кладе їх
    у `не_взято_кодом` паспорта (рядок 3191).

    `внутрішня` — оновлення паспорта, розібране ТИМ САМИМ шляхом, що переклад сценарію
    (`прийняти_вхід("scenario", …)`: пари → поле й уривок у `quotes`, коди поза переліком — у
    `незнайомі`). `need` стає й старою темою питання (`question_about`: look / app) — її читають
    гілки оцінки й довідки показу. `частини` — сирі частини відповіді; судить їх шов (`суд_частин`).
    Не JSON чи без `text` — причина, і хід іде шляхом main (як відмова перекладача доти)."""
    об, чому_не = _обʼєкт(відповідь)
    незакрито = []
    if not isinstance(об, dict):
        об, незакрито = _незакритий(відповідь), [НЕЗАКРИТИЙ_ОБʼЄКТ]
    if not isinstance(об, dict):
        об, незакрито = _лагоджена_форма(відповідь)
    if not isinstance(об, dict):
        return dict(внутрішня={}, частини={}, незнайомі=[], невідомо=[], заглушки=[],
                    причина="not_json_object: %s" % (чому_не or type(об).__name__))
    оновлення = об.get("update") if isinstance(об.get("update"), dict) else {}
    # ── ЧАСТИНИ ХОДУ, ВКЛАДЕНІ В `update` (рядок 2420) ─────────────────────────────────────
    # ЩО БУЛО. Живий прогін пачки 2 (MamayLM, сцена 6б «фото + оціни мій образ»): у 15 з 15
    # записаних ходів модель ПОЗНАЧИЛА `need: look`, але в 11 поклала `need` і `text` усередину
    # `update`. Код читав їх лише поруч з `update`: там — пусто, тож «no_text_field», хід ішов
    # шляхом main (виклик 0) і замість оцінки складався паспорт сценарію. Провалювались рівно
    # вкладені відповіді; ті 4, де частини стояли поруч, відкрили оцінку.
    # ЩО СТАЛО. Коди частин (`_ЧАСТИНИ`) — не поля сценарію (переліки `внутрішня_мова.СЦЕНАРІЙ`
    # цих імен не мають), тож частина, яку модель поклала в `update`, і є її частиною ходу: код
    # бере ЇЇ код звідти, де вона його написала, сам нічого не розпізнає (п.12, п.14). Частина,
    # що стоїть і поруч, сильніша — вкладена тоді лишається незнайомою. Перенесене — у звіт
    # (`перенесено`), щоб формат моделі було видно.
    перенесено = [к for к in _ЧАСТИНИ if к in оновлення and к not in об]
    if перенесено:
        об = dict(об, **{к: оновлення[к] for к in перенесено})
        оновлення = {к: в for к, в in оновлення.items() if к not in перенесено}
    р = прийняти_вхід("scenario", _json_.dumps(оновлення, ensure_ascii=False))
    незнайомі = list(р["незнайомі"]) + ["%s" % к for к in об if к not in _ЧАСТИНИ + ("update",)]
    частини = {}
    need = _код(об.get("need"))
    if need in _ВМ.ПОТРЕБИ:
        частини["need"] = need
    elif not _порожнє(need):
        незнайомі.append("need=%s" % need)
    зайве_тексту = []
    for к in ("text", "invite", "ask"):
        т = об.get(к)
        # `text` переліком рядків без `about` (рядок 6067: сцена 24 seed3_03, сцена 22 seed1_03 — «["У тебе робочий день
        # в офісі, і ти хочеш приховати животик. Зрозуміла."]»): доти хід ішов як `no_text_field` шляхом паспорта, і
        # записане `goal_zones` губилось. Про що речення, код не знає, тож показує лише перше з кількох слів, як
        # `says` (рядки 4361, 4620); решта — у `відкинуто` (`extra_sentence`). При `need` app чи look бульбашку пише
        # код (рядок 3742), і такий текст («Я подивлюся… і відповім») не показується
        if к == "text" and isinstance(т, list) and т and all(isinstance(x, str) for x in т) \
                and частини.get("need") not in ("app", "look"):
            шматки = [x for x in _РЕЧЕННЯ.split(" ".join(т)) if x.strip()]
            т = next((x for x in шматки if len(x.split()) > 1), шматки[0] if шматки else "")
            if len(шматки) > 1:
                зайве_тексту.append(dict(частина="text", чому="extra_sentence", про=[],
                                         зняте=" ".join(x for x in шматки if x is not т)))
        if isinstance(т, str) and not _порожнє(т) and not _ВМ.невідомо(т):
            частини[к] = " ".join(т.split())
    речення = _речення_тексту(об.get("text"))
    if речення:
        # Коди `about` — ті самі, що в `update`: поле, яке шов переніс на своє (`weather_feel->precipitation`,
        # `goal_zones->open_zones`), і в реченні про нього стоїть уже на своєму місці (рядок 3741: ЖИВІ-14 №3 —
        # дощ записано опадами, а речення про `weather_feel` суд знімав як «не про записане»). Поле, яке модель
        # написала в `update`, а код не взяв (невідомо чи код поза переліком; `not_taken`, рядок 3653), — теж про її
        # лист, не тема поради чи обіцянка: слід лишається в `не_взято` чи `незнайомі`, а речення не знімається.
        на_своє = dict(x.split("->", 1) for x in р.get("перенесено") or () if "->" in x)
        не_взяв = set(р["невідомо"]) | {re.split(r"[\[=]", x, 1)[0] for x in р["незнайомі"] if isinstance(x, str)}
        частини["text"] = _бульбашка([р_ for р_, _ in речення])
        частини["text_parts"] = []
        for р_, п in речення:
            п = list(dict.fromkeys(на_своє.get(к, к) for к in п))
            нв = [к for к in п if к in оновлення and к in не_взяв]
            частини["text_parts"].append(dict(about=п, says=р_, **({"not_taken": нв} if нв else {})))
    теми = [_код(т) for т in (об.get("invite_topics") or []) if isinstance(т, str)] \
        if isinstance(об.get("invite_topics"), list) else []
    частини["invite_topics"] = [т for т in dict.fromkeys(теми) if т]
    ask_code = _код(об.get("ask_code"))
    if ask_code and not _порожнє(ask_code):
        частини["ask_code"] = ask_code
    в = р["внутрішня"]
    шапка = _шапка(об.get("header"), незнайомі, в)
    if шапка:
        частини["header"] = шапка
    if частини.get("need") in ("app", "look"):
        в["question_about"] = частини["need"]
    в, зняте_оцінки = _бажання_оцінки(в, частини.get("need"))
    # ПИТАННЯ, НА ЯКЕ ВІДПОВІДАЄ НЕ ВОНА (рядок 3742, ЖИВІ-14 №10): при `need` app чи look її бульбашку пише код
    # (оцінка образу чи перекладач із відповіддю стилістки або помічниці), а `text` каже лише записане — коли
    # не записано нічого, речень нема. MamayLM на фото з «оціни мій образ» двічі дала `need: look` і
    # `text: [{"about": []}]`; код рахував це битим форматом (`no_text_field`), і репліка йшла в сценарій.
    причина = None if частини.get("text") or частини.get("ask") or частини.get("need") in ("app", "look") \
        else "no_text_field"
    текст, зняте, не_про_записане = _текст_до_показу(частини, в)
    чужі_ключі = _ключі_поза_схемою(незнайомі, оновлення)
    return dict(внутрішня=в, частини=частини, незнайомі=незнайомі, невідомо=р["невідомо"],
                не_взято=[невзяте_рядком(к, оновлення.get(к)) for к in р["невідомо"]] + р["не_взято"],
                заглушки=_заглушки(об), причина=причина, текст=текст,
                повтор=("unknown_key: " + ", ".join(чужі_ключі)) if чужі_ключі else None,
                перенесено=["update.%s" % к for к in перенесено] + ["update.%s" % к for к in р.get("перенесено") or ()]
                + незакрито + зняте_оцінки,
                відкинуто=зайве_тексту + не_про_записане
                + ([dict(частина="text", чому="question_in_text", зняте=зняте)] if зняте else []))


def прийняти_хід_плиток(відповідь):
    """Відповідь ходу плиток → dict тієї самої форми, що `прийняти_розмову`: з `update` код бере лише
    `ПОЛЯ_ХОДУ_ПЛИТОК` (розбір — той самий `прийняти_вхід("scenario", …)`), решта ключів — у `незнайомі`; частин
    і тексту в цього ходу нема, тож без `text` хід не битий. Не JSON — причина, і показ робить один повтор."""
    об, чому_не = _обʼєкт(відповідь)
    if not isinstance(об, dict):
        об = _незакритий(відповідь)
    if not isinstance(об, dict):
        return dict(внутрішня={}, частини={}, незнайомі=[], невідомо=[], не_взято=[], заглушки=[], текст="",
                    причина="not_json_object: %s" % (чому_не or type(об).__name__), перенесено=[], відкинуто=[])
    оновлення = об.get("update") if isinstance(об.get("update"), dict) else {}
    взято = {к: в for к, в in оновлення.items() if к in ПОЛЯ_ХОДУ_ПЛИТОК}
    р = прийняти_вхід("scenario", _json_.dumps(взято, ensure_ascii=False))
    незнайомі = list(р["незнайомі"]) + ["update.%s" % к for к in оновлення if к not in ПОЛЯ_ХОДУ_ПЛИТОК] \
        + [к for к in об if к != "update"]
    return dict(внутрішня=р["внутрішня"], частини={}, незнайомі=незнайомі, невідомо=р["невідомо"],
                не_взято=[невзяте_рядком(к, взято.get(к)) for к in р["невідомо"]] + р["не_взято"],
                заглушки=_заглушки(об),
                причина=None, текст="", перенесено=["update.%s" % к for к in р.get("перенесено") or ()], відкинуто=[])


# ── СУД ЧАСТИН ВІДПОВІДІ (п.9 — ЗАБЕЗПЕЧУЄ КОД) ───────────────────────────────────────
# Речення рахуються за знаками кінця речення — розділові знаки, не слова (п.12): код не читає,
# ЩО вона чи модель сказали, лише ФОРМУ — чи це питання і скільки речень.
_РЕЧЕННЯ = re.compile(r"(?<=[.!?…])\s+")
_ПИТАННЯ = re.compile(r"[?？]")


def _без_питань(текст):
    """(текст без речень із «?», зняті речення) — форма, не слова: питати її може лише код."""
    речення = [р for р in _РЕЧЕННЯ.split(текст or "") if р.strip()]
    return " ".join(р for р in речення if not _ПИТАННЯ.search(р)), [р for р in речення if _ПИТАННЯ.search(р)]


# Рядок 314: «…без підборів можеш ще розказати… а якщо ні - я підберу сама» — підтвердження й запрошення
# зліплені без крапки, тире — дефісом. Знаки — форма, не слова (п.12): шматок без знака кінця речення
# дістає крапку, перш ніж за ним стане наступний, а дефіс чи коротке тире між словами стає «—».
_КІНЕЦЬ_ШМАТКА = re.compile(r"[.!?…][»)\"]*$")
_ТИРЕ = re.compile(r"(?<=\S) [-–] (?=\S)")


def _бульбашка(шматки):
    """Шматки репліки (текст, питання, запрошення) → один текст: кожен — окремим реченням, тире — «—»."""
    шматки = [_ТИРЕ.sub(" — ", ш.strip()) for ш in шматки if ш and ш.strip()]
    return " ".join(ш if і == len(шматки) - 1 or _КІНЕЦЬ_ШМАТКА.search(ш) else ш + "."
                    for і, ш in enumerate(шматки))


# ── РЕЧЕННЯ `text` З КОДАМИ (рядок 3452) ──────────────────────────────────────────────
# ЩО БУЛО. Суд бачив у `text` лише «?»: живі 13 — «Розкажи про стиль, який тобі подобається.» (№2, `invite_topics:
# [jewelry]`, а питають і стиль), «Я запропоную тобі прикраси та стиль для цього образу.» (№1, №8), «Тоді я можу
# запропонувати тобі однотонні речі.» (№7), «Розкажи про взуття та прикраси…» (№9) — друга тема й обіцянка йшли
# повз суд запрошення (до трьох тем, без повторів, п.9), бо їх форма — без знака питання.
# ЩО СТАЛО. `text` — перелік речень, кожне з кодами того, про що воно (`about`): поля `update` цього ходу чи
# `her_question`. Код слів не читає (п.12): показує речення, коди якого всі записані цим ходом (після сторожа
# вигадок) чи `her_question`; решта — у `відкинуто` (`not_about_recorded`) з кодами, звіт власника бачить, про
# що модель хотіла сказати. Тема поради в `text` так стає видна кодом і не обходить суд `invite`.
# `text` рядком (старий формат) — як доти: суд лише «?».
# ОДНЕ РЕЧЕННЯ НА `says` (рядок 4361, ЖИВІ-20 №5–9, №13, `VIDPOVIDI/seed3_01`). Схема каже `says` — «one sentence»,
# а модель писала два: переказ і прохання без «?» — «Зрозуміла, вранці ти підеш на йогу… у кафе. Розкажи мені ще про
# те, де саме відбудеться ця зустріч.» (`about` — записані поля, тож речення йшло цілим). Питання про місце код зняв
# (`ask` → `not_required_after_turn`), а жінка читала його з `text`: 3 з 6 перших ходів. Код слів не читає (п.12):
# ділить `says` за розділовими знаками, як `too_many_sentences` поради, і показує перше речення; решта — у `відкинуто`
# (`extra_sentence`) з кодами `about`. Друге речення-переказ («Надворі мороз.», №5) теж іде у `відкинуто`: краще
# недоказати записане, ніж показати питання, якого п.9 не дозволяє.
# ОДНЕ СЛОВО — НЕ РЕЧЕННЯ ПРО ЗАПИСАНЕ (рядок 4620, ЖИВІ-22 №1 і №5, `VIDPOVIDI/seed3_01`). «Зрозуміла. Це святкова
# вечірка в ресторані, надворі мороз.» — модель відокремила крапкою слово-згоду, і бульбашкою першого ходу стало саме
# «Зрозуміла.», а переказ трьох записаних полів пішов у `відкинуто`. Шматок з одного слова (без пробілу всередині)
# не може переказати жодного поля з `about` — форма, не слова (п.12): показується перший шматок із кількох слів, а
# шматок з одного слова — лише коли інших нема (хід плиток: «text is one short word»); решта — `extra_sentence`.
# РЕЧЕННЯ ПРО ЗАПИСАНУ МЕТУ — НЕ ЗАЙВЕ (рядок 6073, ОЦІНКА-ЖИВИЙ-14). Модель кладе мету другим реченням того самого
# `says`: «Ти йдеш на вечірку в клуб, хочеш привернути до себе увагу та зручно танцювати. Пам'ятаймо про твій запит
# сховати живіт.» (`about` — occasion, intent, goal_zones, movement). Правило одного речення знімало саме його: у
# сценах 12–16 живіт у бульбашці 0 з 5, хоч `goal_zones` записано, — вона не бачить, що мету почули (п.9). Код
# слів не читає (п.12): на кожен код мети (`goal`, `goal_zones`, `goal_extra`), записаний цим ходом і названий в
# `about`, показується ще одне речення з кількох слів. Бюджет «по реченню на кожен код `about`» повертав питання-
# накази рядка 4361 («Розкажи мені про місце проведення…» — Ж20 №6, №9, №13) і обіцянки («Обираємо лук…»), тож
# лише мета; replay Ж20–22 — бульбашки ті самі (`проби/хід_форми_6067.py`).
ПРО_ЇЇ_ПИТАННЯ = "her_question"
_КОДИ_МЕТИ = ("goal", "goal_zones", "goal_extra")
# РЕЧЕННЯ ПРО ОШАТНІСТЬ — НЕ ДЛЯ НЕЇ (рядок 6189, ж15): ошатність — внутрішня шкала (межа `без_шкал`), а речення з
# formality в `about` правило R13 («restates it») пропускало — «з рівнем одяру 3–4», «середньої формальності», 5 з 28
# бульбашок. Код слів не читає (п.12): речення, у `about` якого є formality, знімається цілим (`about_scale`).
_КОДИ_ШКАЛИ = ("formality",)


def _речення_тексту(text):
    """`text` переліком [{about, says}] → [(речення, [коди about])]; рядок чи порожнє — []."""
    if not isinstance(text, list):
        return []
    вих = []
    for x in text:
        т = x.get("says") if isinstance(x, dict) else None
        if not isinstance(т, str) or _порожнє(т) or _ВМ.невідомо(т):
            continue
        про = x.get("about")
        про = [про] if isinstance(про, str) else про if isinstance(про, list) else []
        вих.append((" ".join(т.split()), [к for к in dict.fromkeys(_код(к) for к in про if isinstance(к, str)) if к]))
    return вих


def _текст_до_показу(частини, записано):
    """(текст без питань, зняті речення з «?», відкинуті речення не про записане) — речення `text`, які жінка
    прочитає: про поля `записано` цього ходу чи про її питання (`ПРО_ЇЇ_ПИТАННЯ`), і ні про шкалу (`_КОДИ_ШКАЛИ`).
    `записано` None — без цього суду (лише «?»)."""
    ч, відкинуто = частини or {}, []
    текст, речення = ч.get("text"), ч.get("text_parts")
    if isinstance(речення, list) and записано is not None:
        лишено = []
        for р in речення:
            коди = list((р or {}).get("about") or [])
            чуже = [к for к in коди if к != ПРО_ЇЇ_ПИТАННЯ and к not in записано
                    and к not in ((р or {}).get("not_taken") or ())]
            шкала = [к for к in коди if к in _КОДИ_ШКАЛИ]
            if шкала:
                відкинуто.append(dict(частина="text", чому="about_scale", про=коди, зняте=р.get("says")))
            elif коди and not чуже:
                шматки = [x for x in _РЕЧЕННЯ.split(р.get("says") or "") if x.strip()] or [""]
                довгі = [x for x in шматки if len(x.split()) > 1] or шматки[:1]
                показ = довгі[:1 + len([к for к in коди if к in _КОДИ_МЕТИ and к in записано])]
                далі = [x for x in шматки if x not in показ]
                лишено += показ
                if далі:
                    відкинуто.append(dict(частина="text", чому="extra_sentence", про=коди, зняте=" ".join(далі)))
            else:
                відкинуто.append(dict(частина="text", чому="not_about_recorded", про=коди, чуже=чуже,
                                      зняте=р.get("says")))
        текст = _бульбашка(лишено)
    текст, зняте = _без_питань(текст)
    return текст, зняте, відкинуто


def суд_частин(частини, дозволені, обовʼязкове, дані=(), записано=None):
    """Частини відповіді моделі → (текст бульбашки, теми запрошення, відкинуто, бракує_обовʼязкового,
    запрошення_питанням, показані).

    `дозволені` — теми поради, які код дозволяє на стані ПІСЛЯ ходу (`теми_дозволені`);
    `обовʼязкове` — обовʼязкові коди на тому самому стані; `дані` — коди тем, які в цій розмові вже
    пропонували (`поради_дані`); `записано` — поля, які код записав цим ходом: речення `text` про інше
    відкидаються (`_текст_до_показу`). `показані` — коди тем, які вона ПРОЧИТАЄ в запрошенні (дозволені й
    ні): усі лягають у `поради_дані`. Відкинуте не губиться мовчки: кожен
    рядок `відкинуто` — {частина, чому} кодами, і він їде в запис виклику (звіт власника)."""
    import паспорт_нагоди as _ПН
    ч = частини or {}
    текст, зняте, відкинуто = _текст_до_показу(ч, записано)
    if зняте:
        відкинуто.append(dict(частина="text", чому="question_in_text", зняте=зняте))
    шматки = [текст] if текст else []
    ask = ч.get("ask")
    if ask:
        if ч.get("ask_code") not in обовʼязкове:
            відкинуто.append(dict(частина="ask", чому="not_required_after_turn", код=ч.get("ask_code")))
        else:
            шматки.append(ask)
    бракує = [к for к in обовʼязкове if not (ask and ч.get("ask_code") == к)]
    # ОДНА НЕДОЗВОЛЕНА ТЕМА НЕ ЗНІМАЄ ДОЗВОЛЕНИХ (рядок 1001): доти запрошення на [register, jewelry,
    # movement] при дозволених [jewelry, register] відкидалось цілим, `поради_дані` лишались порожні.
    # Тепер недозволене відкидається поіменно (запис у `відкинуто`), дозволене лишається; цілим
    # запрошення відкидається, лише коли дозволених не лишилось.
    # ТЕКСТ ЗАПРОШЕННЯ НЕСЕ ВСІ СВОЇ ТЕМИ (рядок 2840). Код слів не править (п.12): запрошення або йде цілим,
    # або не йде. Доти цілим ішло й тоді, коли частина тем недозволена, а в `поради_дані` лягали лише дозволені:
    # Д3 живого пачки 5 — «Розкажи про мету…, чи плануєш прикраси та яка очікується температура?» при
    # дозволених [makeup, jewelry, register]; мету й температуру вона прочитала, а код їх «не пропонував» і
    # міг запропонувати знову — повтор після ігнорування (п.9). Тепер: тема, яку вже пропонували (`дані`), —
    # повтор у самому тексті, і запрошення відкидається цілим (`topic_repeated`); решта недозволених
    # лишається в тексті (рядок 1001) і разом із дозволеними повертається `показані` — у `поради_дані`.
    всі_теми, invite = list(ч.get("invite_topics") or []), ч.get("invite")
    теми = [т for т in всі_теми if т in дозволені]
    недозволені = [т for т in всі_теми if т not in дозволені]
    повтори = [т for т in недозволені if т in set(дані or ())]
    показані = []
    if invite or всі_теми:
        чому = ("required_this_turn" if обовʼязкове else "no_topics" if not всі_теми
                else "no_invite_text" if not invite
                else "too_many_topics" if len(всі_теми) > _ПН.ПОРАД_ЗА_ХІД_МАКС
                else "topic_repeated" if повтори
                else "topic_not_allowed" if not теми
                else "too_many_sentences" if len([р for р in _РЕЧЕННЯ.split(invite) if р.strip()]) > _ПН.ПОРАДА_РЕЧЕНЬ_МАКС
                else None)
        if чому:
            відкинуто.append(dict(частина="invite", чому=чому, теми=всі_теми,
                                  дозволені=list(дозволені), **({"повтори": повтори} if повтори else {})))
            теми = []
        else:
            показані = list(всі_теми)
            if недозволені:
                відкинуто.append(dict(частина="invite_topics", чому="topic_not_allowed", теми=недозволені,
                                      лишено=теми, дозволені=list(дозволені), показано=True))
            шматки.append(invite)
    # ЗАПРОШЕННЯ ПИТАННЯМ — ПОРАДА, А НЕ ВІДКИНУТЕ (рядок 2814). Живий пачки 5: у всіх 13 повних прогонах і в обох
    # розмовних MamayLM писала `invite` питанням («Чи плануєте ви багато ходити?»), суд відкидав його цілим
    # (`question_in_invite`), і `поради_дані` лишались порожні — поради п.9 жінці не доходили зовсім. Неінвазивність
    # тримає код, не формулювання моделі (п.9): теми дозволені, до трьох, одним реченням, без повторів, не поруч з
    # обовʼязковим питанням. Що відповідати не мусить, каже сталий напис показу під бульбашкою — його ставить
    # `запрошення_питанням`; запрошення без «?» модель і так пише з «можна й ні».
    питанням = bool(теми) and bool(_ПИТАННЯ.search(invite or ""))
    return _бульбашка(шматки), теми, відкинуто, бракує, питанням, показані


# ── РЕМОНТ ПОРАДИ: ОДИН ПОВТОРНИЙ ЗАПИТ ІЗ НАЗВАНОЮ ВАДОЮ (рядок 3930) ─────────────────────────────
# ЩО БУЛО. ЖИВІ-15 №1–9: суд п.9 (`суд_частин`) зняв усі 4 запрошення перших ходів (`too_many_topics` ×2,
# `too_many_sentences`, `required_this_turn`), і жінка не побачила жодної поради (0 з 9). Код слів не править
# (п.12): запрошення або йде цілим, або не йде, — тож знята порада губилась на цьому ході.
# ЩО СТАЛО. Коли вада — у самій формі поради, а обовʼязкового нема й дозволені теми є, показ кличе мовну модель
# ще раз малою задачею (`ПОРАДА`): дозволені теми з описом, вада кодом і знята порада. Відповідь судить той
# самий `суд_частин`; не пройшла — поради на цьому ході нема, як доти (повтору повтору нема).
# `required_this_turn` не ремонтується: поруч з обовʼязковим питанням порада — неправда в одній репліці (Ч-5).
ВАДИ_ПОРАДИ_EN = {
    "too_many_topics": "it was about more than three topics",
    "too_many_sentences": "it was more than one sentence",
    "topic_not_allowed": "none of its topics is an advice topic that applies now",
    "topic_repeated": "it offered again a topic she was already offered in this conversation",
    "no_invite_text": "it named topics but had no sentence",
    "no_topics": "it had a sentence but named no topic codes",
    "no_invite": "your answer had no invitation, though these advice topics apply now",
}


def ремонт_поради(відкинуто, обовʼязкове, дозволені, частини):
    """Що послати на повторний запит поради — {вада, дозволені, запрошення} — або None: запрошення ходу зняв
    суд за вадою форми (`ВАДИ_ПОРАДИ_EN`), обовʼязкового на цьому ході нема, а дозволені теми є."""
    р = next((x for x in відкинуто or () if x.get("частина") == "invite"), None)
    if обовʼязкове or not дозволені or not р or р.get("чому") not in ВАДИ_ПОРАДИ_EN:
        return None
    return dict(вада=р["чому"], дозволені=list(дозволені), запрошення=str((частини or {}).get("invite") or ""))


ПОРАДА = _ЗП_Р.Оголошення(
    задача="порада",
    роль="You are the stylist of a styling app in a live chat with a woman. The app did not show her an "
         "invitation to tell more about this outing: yours broke a rule of the app or was missing. Write it within "
         "the rules.",
    вхід=(
        _ЗП_Р.Поле("advice_topics", "the advice topics you may invite her to tell about now — code: what to "
                                    "invite her to tell", треба=True),
        _ЗП_Р.Поле("defect", "why the app did not show your invitation", треба=True),
        _ЗП_Р.Поле("your_invitation", "the invitation the app did not show",
                   як="keep none of its topics that is not in \"advice_topics\""),
        _ЗП_Р.Поле("her_new_message", "her new message", як="do not invite her to tell what it already says"),
    ),
    правила=(
        # П.9 (20.09, рядки 108 і 114): порада — до трьох тем одним м'яким реченням, без обовʼязкових.
        # Рядок 6192: «no question marks» тут суперечило ходу — суд приймає запрошення питанням (рядок 2814), а R15
        # «?» не забороняє; «to her as «ти»» — у `_ПРАВИЛО_ФОРМИ` і межі `для_неї`, четвертий раз не треба.
        # Рядок 6615 (ЖИВІ-1016-2 №1–3, 10): «…? Можеш пропустити цей крок, якщо не хочеш.», «…? Хоча й без цього образ
        # буде готовий!», «…? І, можливо, …?» — дослівно «saying she may skip it» другим реченням, і суд знімав пораду
        # (`too_many_sentences`, порад 0; ремонтів із двома реченнями 4 з 8). «Можна не відповідати…» під
        # запрошенням-питанням ставить показ сам (`ПОРАДА_НЕОБОВʼЯЗКОВА_П`); тут — лише одне речення.
        "\"invite\" is advice, not your question: exactly one soft sentence about up to three codes from "
        "\"advice_topics\", and nothing after it — no second sentence and no second question; do not add that she "
        "may skip it: the app tells her. \"invite_topics\" are exactly the codes it covers.",
        _ПРАВИЛО_ФОРМИ,
        _ПРАВИЛО_ПРОФІЛЮ,
    ),
    вихід="ПОРАДА_ХОДУ",
    скелет={"invite_topics": ["advice topic codes your invitation covers, up to three"],
            "invite": "one soft invitation sentence"},
    # Рядок 6192: `без_шкал` знято — у вході ремонту шкал нема (теми, вада, запрошення, її лист).
    межі=("лише_вхід", "для_неї"),
    мова_промпту="en",
    сталий_спершу=True,
    наприкінці="Answer: one JSON object following \"answer_schema\" in \"task\".",
)


def промпт_поради(ремонт, слова=""):
    """Промпт повторного запиту поради: `ремонт` — те, що дав `ремонт_поради`; `слова` — її новий лист."""
    р = ремонт if isinstance(ремонт, dict) else {}
    умови = _умови_тем()
    дані = {"advice_topics": {к: умови[к][0] for к in р.get("дозволені") or () if к in умови},
            "defect": ВАДИ_ПОРАДИ_EN.get(р.get("вада")),
            "your_invitation": str(р.get("запрошення") or "").strip() or None,
            "her_new_message": str(слова or "").strip() or None}
    return _json_.dumps(_ЗП_Р.зібрати(ПОРАДА, дані, мова_тексту="Ukrainian"), ensure_ascii=False)


def прийняти_пораду(відповідь, ремонт, паспорт=None, текст=""):
    """Відповідь повторного запиту → dict(текст, теми_поради, запрошення, запрошення_питанням, відкинуто, паспорт).

    Суд — той самий `суд_частин` (дозволені — з `ремонт`, обовʼязкового нема); `текст` — бульбашка ходу після
    суду, порада стає за нею окремим реченням. Показані теми лягають у `поради_дані` паспорта, як на ході."""
    р = ремонт if isinstance(ремонт, dict) else {}
    п = dict(паспорт) if isinstance(паспорт, dict) else {}
    об, _ = _обʼєкт(відповідь)
    об = об if isinstance(об, dict) else {}
    частини = {"invite": " ".join(об["invite"].split())} if isinstance(об.get("invite"), str) \
        and not _порожнє(об["invite"]) else {}
    if isinstance(об.get("invite_topics"), list):
        частини["invite_topics"] = [т for т in dict.fromkeys(_код(т) for т in об["invite_topics"]
                                                              if isinstance(т, str)) if т]
    дані = list(п.get("поради_дані") or [])
    запрошення, теми, відкинуто, _, питанням, показані = суд_частин(
        частини, list(р.get("дозволені") or ()), [], дані=[_ВМ.код("advice_topic", т) for т in дані], записано={})
    if not частини.get("invite") and not частини.get("invite_topics"):
        відкинуто.append(dict(частина="invite", чому="no_invite_text", теми=[]))
    п["поради_дані"] = дані + [к for к in dict.fromkeys(_ВМ.ключ("advice_topic", т) for т in показані)
                               if к and к not in дані]
    return dict(текст=_бульбашка([т for т in (текст, запрошення) if т]) if показані else (текст or ""),
                теми_поради=теми, запрошення=запрошення if показані else "", запрошення_питанням=питанням,
                відкинуто=відкинуто, паспорт=п)


# ══ ЕНДПОЙНТ ════════════════════════════════════════════════════════════════════
def мова(вхід):
    """Ендпойнт моста `мова`. Кожен виклик моделі шару — два кроки (як `паспорт`):
    спершу промпт, потім відповідь моделі. Python між кроками стану не тримає.
      · {тексти, виправ?, речі?} → {промпт, розмітка, вибірка} (`речі` — речі картки, `_абзац_речей`);
        {розмітка, відповідь_моделі} → `прийняти`;
      · {розмова: {нове, історія}, сценарій, паспорт?, фото?, профіль?} → {промпт, вибірка};
        {розмова, відповідь_моделі} → `прийняти_розмову` (М-5: хід розмови одним викликом); без `розмова.нове` —
        хід плиток (`ХІД_ПЛИТОК`, `прийняти_хід_плиток`, рядок 6185);
      · {вхід: вид, слова, контекст?} → {промпт, вибірка}; {вхід, відповідь_моделі} → `прийняти_вхід`;
      · {коментар_з: внутрішня мова коментаря до образу, паспорт?} → `паспорт_з_коментаря`
        (С-2: межі й бажання коментаря — у паспорт сценарію, відкинуті речі — у «не ця»);
      · {паспорт_з: внутрішня, сценарій, вето?, паспорт?, драп_сирий?, фото_речей?,
        речі_з_фото?, слова_ходу?, слова_розмови?, частини?, профіль?, не_взято?} → `паспорт_з_шару` + рядки випадку
        (з `частини` — ще й суд частин ходу розмови: `текст`, `відкинуто`, `бракує_обовʼязкового`);
        `профіль` — кольори людини: з них контраст обличчя для теми «макіяж» (МАК-2);
      · {порада: ремонт_поради, слова} → {промпт, вибірка}; {порада, відповідь_моделі, паспорт, текст} →
        `прийняти_пораду` (рядок 3930: повторний запит знятої поради з вадою кодом);
      · {репліка} → {промпт, вибірка}; {репліка, відповідь_моделі} → `прийняти_репліку`;
      · {повідомлення} → {промпт, розмітка, незнайомі, вибірка}; {розмітка_повідомлень,
        відповідь_моделі} → `прийняти_повідомлення`.
    `вибірка` — поля вибірки моделі для тіла виклику шару (`ВИБІРКА`)."""
    d = _json_.loads(вхід) if isinstance(вхід, str) else (вхід or {})
    дамп = lambda x: _json_.dumps(x, ensure_ascii=False, default=str)
    if d.get("розмова") is not None:
        if d.get("відповідь_моделі") is not None:
            return дамп((прийняти_хід_плиток if хід_плиток(d) else прийняти_розмову)(d["відповідь_моделі"]))
        return дамп(dict(промпт=промпт_розмови(d), вибірка=ВИБІРКА))
    if d.get("вхід"):
        речі = [р for р in d.get("речі") or [] if isinstance(р, dict) and р.get("id")]
        if d.get("відповідь_моделі") is not None:
            return дамп(прийняти_вхід(d["вхід"], d["відповідь_моделі"],
                                      ід_речей=({str(р["id"]) for р in речі} if "речі" in d else None),
                                      слоти_речей={str(р["id"]): _ВМ.код("slot", р.get("слот")) for р in речі
                                                   if _ВМ.код("slot", р.get("слот"))},
                                      слова=(str(d["слова"]) if d.get("слова") is not None else None)))
        контекст = d.get("контекст")
        if речі:     # речі образу для коментаря — кодами, id для точного посилання
            контекст = dict(контекст or {}, items=[dict(
                id=str(р["id"]), slot=_ВМ.код("slot", р.get("слот")) or U,
                name={"free_text": str(р.get("назва") or ""), "lang": "uk"}) for р in речі])
        return дамп(dict(промпт=промпт_входу(d["вхід"], d.get("слова"), контекст), вибірка=ВИБІРКА))
    if d.get("коментар_з") is not None:
        return дамп(паспорт_з_коментаря(d["коментар_з"],
                                        паспорт_досі=(d.get("паспорт") if isinstance(d.get("паспорт"), dict) else None)))
    if d.get("паспорт_з") is not None:
        import паспорт_нагоди as _ПН
        р = паспорт_з_шару(d["паспорт_з"], d.get("сценарій") or {}, d.get("вето"),
                           паспорт_досі=(d.get("паспорт") if isinstance(d.get("паспорт"), dict) else None),
                           драп=(d.get("драп_сирий") or None), фото=(d.get("фото_речей") or None),
                           речі_з_фото=d.get("речі_з_фото"),
                           слова_ходу=(d.get("слова_розмови") or d.get("слова_ходу") or ""),
                           частини=(d.get("частини") if isinstance(d.get("частини"), dict) else None),
                           контраст=контраст_профілю(d.get("профіль")),
                           не_взято=(d.get("не_взято") if isinstance(d.get("не_взято"), list) else None))
        return дамп(dict(р, випадок=_ПН.паспорт_рядком(р["паспорт"]),
                         випадок_людині=_ПН.паспорт_рядком_людині(р["паспорт"]),
                         # ШМАТКИ З КЛЮЧАМИ — поруч із рядком (Л-9): показ вішає піктограму
                         # на ключ поля, а не на позицію шматка (п.12).
                         випадок_шматки=_ПН.паспорт_шматками_людині(р["паспорт"])))
    # РЕМОНТ ПОРАДИ (рядок 3930): {порада: ремонт_поради, слова} → промпт; з `відповідь_моделі` — суд і `поради_дані`
    if isinstance(d.get("порада"), dict):
        if d.get("відповідь_моделі") is not None:
            return дамп(прийняти_пораду(d["відповідь_моделі"], d["порада"], d.get("паспорт"), d.get("текст") or ""))
        return дамп(dict(промпт=промпт_поради(d["порада"], d.get("слова") or ""), вибірка=ВИБІРКА))
    if d.get("репліка") is not None:
        if d.get("відповідь_моделі") is not None:
            return дамп(прийняти_репліку(d["відповідь_моделі"], d["репліка"], d.get("запрошення") or ""))
        return дамп(dict(промпт=промпт_репліки(d["репліка"]), вибірка=ВИБІРКА))
    if d.get("розмітка_повідомлень") is not None:
        return дамп(прийняти_повідомлення(d["розмітка_повідомлень"], d.get("відповідь_моделі")))
    if d.get("повідомлення") is not None:
        р = розмітити_повідомлення(d["повідомлення"])
        return дамп(dict(промпт=(промпт_повідомлень(р) if р else ""), розмітка=р,
                         незнайомі=незнайомі_заяви(d["повідомлення"]), вибірка=ВИБІРКА))
    if d.get("відповідь_моделі") is not None:
        return дамп(прийняти(d.get("розмітка") or [], d.get("відповідь_моделі")))
    р = розмітити(d.get("тексти") or {}, d.get("виправ") if isinstance(d.get("виправ"), dict) else None)
    return дамп(dict(промпт=(промпт(р, d.get("речі")) if р else ""), розмітка=р, вибірка=ВИБІРКА))
